"""Core pure mathematics (A Level): in-depth lessons for Trigonometry and Coordinate Geometry.

KKEVO draft material for review. Topics: Identities (compound, double and half angles, harmonic form, solving
equations) and Conic sections (circles, parabolas, ellipses, hyperbolas, tangents and normals). These lessons go
deeper than the overview lessons in a_pure_core.py, which stay in place.
Angles are in degrees where a degree sign is shown; calculus and radian work uses radians.
"""

from .dsl import *  # noqa: F403

COURSE = [("pure-mathematics-with-mechanics", "lower-sixth"),
          ("pure-mathematics-with-statistics", "lower-sixth"),
          ("pure-mathematics-with-mechanics", "upper-sixth"),
          ("pure-mathematics-with-statistics", "upper-sixth")]

MODULE = "Trigonometry & Coordinate Geometry"

LESSONS = []

# ---------------------------------------------------------------- Identities: compound angles
LESSONS.append(lesson(
    module=MODULE,
    topic="Identities",
    title="Compound-angle formulae",
    slug="pt-compound-angle-formulae",
    minutes=22,
    summary="Expand sin(A ± B), cos(A ± B) and tan(A ± B), use them for exact values and proofs, solve equations such as sin(x + 30°) = 2 cos x, and find the angle between two lines.",
    objectives=[
        "Write down and use the compound-angle formulae for sine, cosine and tangent",
        "Find exact values of angles such as 15° and 75°",
        "Prove identities and solve equations that contain sin(x ± a), cos(x ± a) or tan(x ± a)",
        "Find the angle between two lines from their gradients",
    ],
    key_concepts=["Compound angle", "sin(A ± B)", "cos(A ± B)", "tan(A ± B)", "Exact value", "Angle between two lines"],
    blocks=[
        H("Introduction"),
        T(r"A mobile phone signal is a wave. When two waves meet, for example a signal and its reflection from a building in Douala, the result is a new wave. To describe it we must know how to handle the sine or cosine of a **sum of two angles**, such as $\sin(\omega t + \phi)$."),
        T(r"Your calculator can find $\sin 75^\circ$, but an exam often asks for the **exact value**, with surds. The compound-angle formulae let you build $75^\circ$ from angles you already know: $45^\circ + 30^\circ$." "\n\n" r"In this lesson angles are in degrees. The formulae are true in radians too."),
        H("The formulae"),
        D(r"These are true for all angles $A$ and $B$. They are identities, so they hold for every value, not just a few.", title="Sine and cosine",
          formula=r"\begin{aligned}\sin(A + B) &= \sin A\cos B + \cos A\sin B\\ \sin(A - B) &= \sin A\cos B - \cos A\sin B\\ \cos(A + B) &= \cos A\cos B - \sin A\sin B\\ \cos(A - B) &= \cos A\cos B + \sin A\sin B\end{aligned}",
          note=r"In the cosine formulae the sign in the middle is **opposite** to the sign inside the bracket."),
        D(r"Divide $\sin(A \pm B)$ by $\cos(A \pm B)$, then divide top and bottom by $\cos A\cos B$.", title="Tangent",
          formula=r"\tan(A + B) = \frac{\tan A + \tan B}{1 - \tan A\tan B}, \qquad \tan(A - B) = \frac{\tan A - \tan B}{1 + \tan A\tan B}"),
        T(r"**Why not $\sin(A + B) = \sin A + \sin B$?** Try $A = B = 45^\circ$. The left side is $\sin 90^\circ = 1$. The right side is $\frac{\sqrt{2}}{2} + \frac{\sqrt{2}}{2} \approx 1.41$. The sine function does not split over a sum." "\n\n" r"**Where does $\cos(A - B)$ come from?** Put two points on the unit circle at angles $A$ and $B$: $(\cos A, \sin A)$ and $(\cos B, \sin B)$. Their distance apart depends only on the angle $A - B$ between them. Working out that distance in two ways gives $\cos(A - B) = \cos A\cos B + \sin A\sin B$, and every other formula follows by replacing $B$ with $-B$ or $A$ with $90^\circ - A$."),
        H("Exact values"),
        EX("Worked example 1: cos 15°", intro=r"Find the exact value of $\cos 15^\circ$.", steps=[
            S(r"Write $15^\circ$ using known angles", math=r"15^\circ = 45^\circ - 30^\circ"),
            S("Expand with the cosine formula", math=r"\cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ"),
            S("Substitute the exact values", math=r"= \frac{\sqrt{2}}{2}\cdot\frac{\sqrt{3}}{2} + \frac{\sqrt{2}}{2}\cdot\frac{1}{2}"),
            S("Simplify", math=r"\cos 15^\circ = \frac{\sqrt{6} + \sqrt{2}}{4}"),
        ], check=r"\frac{2.4495 + 1.4142}{4} = 0.9659 = \cos 15^\circ"),
        EX("Worked example 2: from given values", intro=r"$A$ and $B$ are acute angles with $\sin A = \frac{3}{5}$ and $\sin B = \frac{5}{13}$. Find $\sin(A + B)$, $\cos(A + B)$ and $\tan(A + B)$.", steps=[
            S("Find the missing cosines (use a right-angled triangle, or $\\cos^2 + \\sin^2 = 1$)", math=r"\cos A = \tfrac{4}{5}, \qquad \cos B = \tfrac{12}{13}"),
            S("Sine of the sum", math=r"\sin(A + B) = \tfrac{3}{5}\cdot\tfrac{12}{13} + \tfrac{4}{5}\cdot\tfrac{5}{13} = \tfrac{36 + 20}{65} = \tfrac{56}{65}"),
            S("Cosine of the sum", math=r"\cos(A + B) = \tfrac{4}{5}\cdot\tfrac{12}{13} - \tfrac{3}{5}\cdot\tfrac{5}{13} = \tfrac{48 - 15}{65} = \tfrac{33}{65}"),
            S("Tangent of the sum", math=r"\tan(A + B) = \frac{56/65}{33/65} = \frac{56}{33}"),
        ], check=r"\left(\tfrac{56}{65}\right)^2 + \left(\tfrac{33}{65}\right)^2 = \tfrac{3136 + 1089}{4225} = 1"),
        TIP(r"A quick safety check: for any angle, $\sin^2 + \cos^2 = 1$. If your $\sin(A + B)$ and $\cos(A + B)$ do not satisfy it, one of them is wrong."),
        H("Proving identities"),
        EX("Worked example 3: a proof", intro=r"Prove that $\sin(x + 30^\circ) + \cos(x + 60^\circ) \equiv \cos x$.", steps=[
            S("Expand the first term", math=r"\sin(x + 30^\circ) = \sin x\cdot\tfrac{\sqrt{3}}{2} + \cos x\cdot\tfrac{1}{2}"),
            S("Expand the second term", math=r"\cos(x + 60^\circ) = \cos x\cdot\tfrac{1}{2} - \sin x\cdot\tfrac{\sqrt{3}}{2}"),
            S("Add: the $\\sin x$ terms cancel", math=r"\tfrac{\sqrt{3}}{2}\sin x - \tfrac{\sqrt{3}}{2}\sin x + \tfrac{1}{2}\cos x + \tfrac{1}{2}\cos x = \cos x"),
        ], check=r"x = 10^\circ:\ \sin 40^\circ + \cos 70^\circ = 0.6428 + 0.3420 = 0.9848 = \cos 10^\circ"),
        H("Solving equations"),
        EX("Worked example 4: an equation", solve=r"\sin(x + 30^\circ) = 2\cos x, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Expand the left side", math=r"\tfrac{\sqrt{3}}{2}\sin x + \tfrac{1}{2}\cos x = 2\cos x"),
            S("Collect the cosine terms on one side", math=r"\tfrac{\sqrt{3}}{2}\sin x = \tfrac{3}{2}\cos x"),
            S(r"Divide by $\cos x$ (it is not zero, because $\cos x = 0$ makes the equation $\pm\frac{\sqrt{3}}{2} = 0$, false)", math=r"\tan x = \frac{3}{\sqrt{3}} = \sqrt{3}"),
            S("Solve in the range", math=r"x = 60^\circ \text{ or } 240^\circ"),
        ], check=r"x = 60^\circ:\ \sin 90^\circ = 1 = 2\cos 60^\circ"),
        EX("Worked example 5: the angle between two lines", intro=r"The lines $y = 3x$ and $y = \frac{1}{2}x + 1$ make angles $A$ and $B$ with the $x$-axis. Find the acute angle between them.", steps=[
            S("Gradients are tangents of the angles", math=r"\tan A = 3, \qquad \tan B = \tfrac{1}{2}"),
            S("The angle between the lines is $A - B$", math=r"\tan(A - B) = \frac{3 - \frac{1}{2}}{1 + 3\cdot\frac{1}{2}} = \frac{2.5}{2.5} = 1"),
            S("Take the inverse tangent", math=r"A - B = 45^\circ"),
        ], check=r"\arctan 3 = 71.57^\circ,\ \arctan 0.5 = 26.57^\circ,\ \text{difference } 45^\circ"),
        H("Common mistakes"),
        MISTAKE(r"Using $\sin(A + B) = \sin A + \sin B$", r"The compound formula has two products. Test your result with simple angles, such as $A = B = 45^\circ$, before you trust it."),
        MISTAKE("Wrong sign in the cosine formulae", r"$\cos(A + B) = \cos A\cos B \mathbf{-} \sin A\sin B$. The signs in the middle are opposite to those inside the bracket, for cosine only."),
        MISTAKE("Using decimals in an exact-value question", r"If the question says exact, keep surds such as $\sqrt{6}$ and $\sqrt{2}$. A decimal like $0.9659$ earns no credit."),
        QUIZ(r"Which expression is equal to $\cos(x - 40^\circ)$?",
             [r"$\cos x\cos 40^\circ - \sin x\sin 40^\circ$", r"$\cos x\cos 40^\circ + \sin x\sin 40^\circ$", r"$\sin x\cos 40^\circ - \cos x\sin 40^\circ$", r"$\cos x - \cos 40^\circ$"], 1,
             r"For $\cos(A - B)$ the middle sign is plus: $\cos A\cos B + \sin A\sin B$.",
             hint="Which sign does the middle of the cosine formula take when the bracket has a minus?",
             feedback=[r"That is $\cos(x + 40^\circ)$: you kept the minus sign from the bracket.", "", r"That is $\sin(x - 40^\circ)$, a different formula.", r"Cosine does not split over a difference."]),
        QUIZ(r"What is $\sin 50^\circ\cos 20^\circ - \cos 50^\circ\sin 20^\circ$?",
             [r"$\sin 70^\circ$", r"$\cos 70^\circ$", r"$\sin 30^\circ$", r"$\sin 50^\circ - \sin 20^\circ$"], 2,
             r"The expression matches $\sin A\cos B - \cos A\sin B = \sin(A - B)$, so it equals $\sin 30^\circ = \frac{1}{2}$.",
             feedback=[r"That would need a plus sign between the products.", r"The pattern sine-cosine minus cosine-sine is a sine formula.", "", r"Sine does not split over a difference."]),
        H("Practice questions"),
        PQ(r"Prove that $\sin(A + B)\sin(A - B) \equiv \sin^2 A - \sin^2 B$.",
           r"$\sin(A + B)\sin(A - B) = (\sin A\cos B + \cos A\sin B)(\sin A\cos B - \cos A\sin B) = \sin^2 A\cos^2 B - \cos^2 A\sin^2 B$. Replace $\cos^2 B = 1 - \sin^2 B$ and $\cos^2 A = 1 - \sin^2 A$: $= \sin^2 A(1 - \sin^2 B) - (1 - \sin^2 A)\sin^2 B = \sin^2 A - \sin^2 A\sin^2 B - \sin^2 B + \sin^2 A\sin^2 B = \sin^2 A - \sin^2 B$."),
        PQ(r"Solve $\sin(x + 60^\circ) = 2\sin x$ for $0^\circ \leq x \leq 360^\circ$.",
           r"Expand: $\frac{1}{2}\sin x + \frac{\sqrt{3}}{2}\cos x = 2\sin x$, so $\frac{\sqrt{3}}{2}\cos x = \frac{3}{2}\sin x$, giving $\tan x = \frac{\sqrt{3}}{3} = \frac{1}{\sqrt{3}}$. So $x = 30^\circ$ or $210^\circ$. Check $x = 30^\circ$: $\sin 90^\circ = 1 = 2\sin 30^\circ$."),
        PQ(r"Given that $\tan(x + 45^\circ) = 2$, find $\tan x$, and hence find $x$ to 1 decimal place for $0^\circ < x < 180^\circ$.",
           r"$\frac{\tan x + 1}{1 - \tan x} = 2 \Rightarrow \tan x + 1 = 2 - 2\tan x \Rightarrow 3\tan x = 1$, so $\tan x = \frac{1}{3}$. Then $x = \arctan\frac{1}{3} = 18.4^\circ$ (1 d.p.). Check: $\tan 63.4^\circ = 2.00$."),
        PQ(r"Find the exact value of $\tan 15^\circ$, giving your answer in the form $a - \sqrt{b}$.",
           r"$\tan 15^\circ = \tan(45^\circ - 30^\circ) = \frac{1 - \frac{1}{\sqrt{3}}}{1 + \frac{1}{\sqrt{3}}} = \frac{\sqrt{3} - 1}{\sqrt{3} + 1}$. Multiply top and bottom by $\sqrt{3} - 1$: $\frac{(\sqrt{3} - 1)^2}{3 - 1} = \frac{4 - 2\sqrt{3}}{2} = 2 - \sqrt{3}$. Check: $2 - 1.7321 = 0.2679 = \tan 15^\circ$."),
        TIP(r"Exam link: Paper 1 (multiple choice) often asks for an exact value or a simplified expression from a compound-angle formula. Paper 2 (Pure Mathematics) asks you to prove an identity or solve an equation, and to show every line of working.", title="Exam link"),
        H("Summary"),
        SUM(r"$\sin(A \pm B) = \sin A\cos B \pm \cos A\sin B$ and $\cos(A \pm B) = \cos A\cos B \mp \sin A\sin B$.",
            r"$\tan(A \pm B) = \dfrac{\tan A \pm \tan B}{1 \mp \tan A\tan B}$.",
            "Build exact values from 30°, 45°, 60° and 90°, for example 15° = 45° − 30° and 75° = 45° + 30°.",
            r"To solve $\sin(x + a) = k\cos x$, expand, collect terms and divide to get $\tan x$.",
            r"The angle between lines with gradients $m_1$ and $m_2$ has $\tan\theta = \left|\dfrac{m_1 - m_2}{1 + m_1 m_2}\right|$."),
    ],
))

# ---------------------------------------------------------------- Identities: double angles
LESSONS.append(lesson(
    module=MODULE,
    topic="Identities",
    title="Double-angle formulae and their uses",
    slug="pt-double-angle-formulae",
    minutes=22,
    summary="Use sin 2A, cos 2A and tan 2A to evaluate, prove and solve, choose the right form of cos 2A, and use cos² and sin² in terms of cos 2A for integration.",
    objectives=[
        "Derive and use the double-angle formulae for sine, cosine and tangent",
        "Choose the most useful form of cos 2A for a given equation",
        "Solve equations without losing solutions by dividing",
        "Write cos²x and sin²x in terms of cos 2x and use them in integration",
    ],
    key_concepts=["Double angle", "Three forms of cos 2A", "Power-reducing formulae", "Triple angle", "Lost solutions"],
    blocks=[
        H("Introduction"),
        T(r"A footballer kicks the ball with speed $u$ at angle $\theta$ to the ground. On level ground the ball lands at distance $R = \dfrac{u^2\sin 2\theta}{g}$. The angle appears **doubled**. To find the best angle, or to compare two angles that give the same distance, you need the double-angle formulae." "\n\n" r"The formulae also help in calculus: they turn $\cos^2 x$ into something you can integrate."),
        H("The formulae"),
        D(r"Put $B = A$ in the compound-angle formulae from the previous lesson.", title="Double angles",
          formula=r"\sin 2A = 2\sin A\cos A, \qquad \tan 2A = \frac{2\tan A}{1 - \tan^2 A}",
          note=r"Both are true for all $A$ (where $\tan 2A$ and $\tan A$ exist)."),
        D(r"Start with $\cos 2A = \cos^2 A - \sin^2 A$. Replace $\sin^2 A$ by $1 - \cos^2 A$, or $\cos^2 A$ by $1 - \sin^2 A$.", title="Three forms of cos 2A",
          formula=r"\cos 2A = \cos^2 A - \sin^2 A = 2\cos^2 A - 1 = 1 - 2\sin^2 A"),
        KEY("Which form to choose", "Pick the form that leaves one trigonometric function only.", cards=[
            [r"Equation has $\sin x$", r"Use $\cos 2x = 1 - 2\sin^2 x$."],
            [r"Equation has $\cos x$", r"Use $\cos 2x = 2\cos^2 x - 1$."],
            [r"Need to integrate", r"Use $\cos^2 x = \frac{1}{2}(1 + \cos 2x)$ and $\sin^2 x = \frac{1}{2}(1 - \cos 2x)$."],
        ]),
        EX("Worked example 1: values from a tangent", intro=r"$A$ is acute and $\tan A = \frac{3}{4}$. Find $\sin 2A$, $\cos 2A$ and $\tan 2A$.", steps=[
            S("Draw a 3, 4, 5 triangle", math=r"\sin A = \tfrac{3}{5}, \qquad \cos A = \tfrac{4}{5}"),
            S(r"$\sin 2A = 2\sin A\cos A$", math=r"2\cdot\tfrac{3}{5}\cdot\tfrac{4}{5} = \tfrac{24}{25}"),
            S(r"$\cos 2A = 2\cos^2 A - 1$", math=r"2\cdot\tfrac{16}{25} - 1 = \tfrac{7}{25}"),
            S("Tangent", math=r"\tan 2A = \frac{24/25}{7/25} = \frac{24}{7}"),
        ], check=r"\frac{2\cdot\frac{3}{4}}{1 - \frac{9}{16}} = \frac{3/2}{7/16} = \frac{24}{7}"),
        EX("Worked example 2: the football", intro=r"A ball is kicked at $20\ \text{m/s}$ and lands at $R = 40\sin 2\theta$ metres (using $g = 10\ \text{m/s}^2$). Find the angles $\theta$, between $0^\circ$ and $90^\circ$, for which it lands $20\ \text{m}$ away.", steps=[
            S("Set $R = 20$", math=r"40\sin 2\theta = 20 \;\Rightarrow\; \sin 2\theta = \tfrac{1}{2}"),
            S("Solve for $2\\theta$ in the range $0^\\circ < 2\\theta < 180^\\circ$", math=r"2\theta = 30^\circ \text{ or } 150^\circ"),
            S("Halve", math=r"\theta = 15^\circ \text{ or } 75^\circ"),
        ], check=r"40\sin 30^\circ = 20,\quad 40\sin 150^\circ = 20"),
        T(r"Notice that $15^\circ$ and $75^\circ$ add up to $90^\circ$. For any range except the maximum, two complementary angles give the same distance on level ground."),
        H("Solving and proving"),
        EX("Worked example 3: do not divide by a function", solve=r"\sin 2x = \sin x, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Use $\\sin 2x = 2\\sin x\\cos x$", math=r"2\sin x\cos x = \sin x"),
            S("Move everything to one side. Do not divide by $\\sin x$, you would lose solutions", math=r"\sin x\,(2\cos x - 1) = 0"),
            S("Case 1", math=r"\sin x = 0 \;\Rightarrow\; x = 0^\circ,\ 180^\circ,\ 360^\circ"),
            S("Case 2", math=r"\cos x = \tfrac{1}{2} \;\Rightarrow\; x = 60^\circ,\ 300^\circ"),
        ], check=r"x = 300^\circ:\ \sin 600^\circ = -0.866 = \sin 300^\circ"),
        EX("Worked example 4: a quadratic in cos x", solve=r"\cos 2x + 3\cos x + 2 = 0, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Use $\\cos 2x = 2\\cos^2 x - 1$", math=r"2\cos^2 x - 1 + 3\cos x + 2 = 0"),
            S("Simplify", math=r"2\cos^2 x + 3\cos x + 1 = 0"),
            S("Factorize", math=r"(2\cos x + 1)(\cos x + 1) = 0"),
            S("Solve", math=r"\cos x = -\tfrac{1}{2} \Rightarrow x = 120^\circ,\ 240^\circ; \qquad \cos x = -1 \Rightarrow x = 180^\circ"),
        ], check=r"x = 180^\circ:\ \cos 360^\circ + 3(-1) + 2 = 0"),
        EX("Worked example 5: a proof", intro=r"Prove that $\dfrac{1 - \cos 2\theta}{\sin 2\theta} \equiv \tan\theta$.", steps=[
            S("Top: use $1 - \\cos 2\\theta = 2\\sin^2\\theta$", math=r"1 - \cos 2\theta = 2\sin^2\theta"),
            S("Bottom: use $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$", math=r"\sin 2\theta = 2\sin\theta\cos\theta"),
            S("Divide and cancel $2\\sin\\theta$", math=r"\frac{2\sin^2\theta}{2\sin\theta\cos\theta} = \frac{\sin\theta}{\cos\theta} = \tan\theta"),
        ]),
        H("Powers of sine and cosine, and integration"),
        D(r"Rearrange the forms of $\cos 2A$ to get formulae that remove the square.", title="Power-reducing formulae",
          formula=r"\cos^2 A = \tfrac{1}{2}(1 + \cos 2A), \qquad \sin^2 A = \tfrac{1}{2}(1 - \cos 2A)"),
        EX("Worked example 6: an integral (radians)", intro=r"Find $\displaystyle\int_0^{\pi/3} \sin^2 x\,dx$, with $x$ in radians.", steps=[
            S("Replace $\\sin^2 x$", math=r"\sin^2 x = \tfrac{1}{2}(1 - \cos 2x)"),
            S("Integrate", math=r"\int \tfrac{1}{2}(1 - \cos 2x)\,dx = \tfrac{1}{2}x - \tfrac{1}{4}\sin 2x"),
            S("Apply the limits", math=r"\left(\tfrac{\pi}{6} - \tfrac{1}{4}\sin\tfrac{2\pi}{3}\right) - 0 = \tfrac{\pi}{6} - \tfrac{\sqrt{3}}{8}"),
        ], check=r"0.5236 - 0.2165 = 0.3071"),
        H("Common mistakes"),
        MISTAKE(r"Writing $\sin 2A = 2\sin A$ or $\cos 2A = 2\cos A$", r"Doubling the angle does not double the function. Test with $A = 30^\circ$: $\sin 60^\circ = 0.866$, but $2\sin 30^\circ = 1$."),
        MISTAKE("Dividing both sides by a trigonometric function", r"In $\sin 2x = \sin x$, dividing by $\sin x$ throws away $x = 0^\circ,\ 180^\circ,\ 360^\circ$. Factorize instead."),
        MISTAKE("Halving the range wrongly", r"If you solve $\sin 2x = k$ for $0^\circ \leq x \leq 360^\circ$, the angle $2x$ goes up to $720^\circ$. Write out all values of $2x$ in that range first, then halve."),
        QUIZ(r"If $\sin\theta = \frac{1}{3}$, what is $\cos 2\theta$?",
             [r"$\frac{2}{3}$", r"$\frac{7}{9}$", r"$\frac{1}{9}$", r"$-\frac{7}{9}$"], 1,
             r"Use $\cos 2\theta = 1 - 2\sin^2\theta = 1 - \frac{2}{9} = \frac{7}{9}$.",
             hint=r"Which form of $\cos 2\theta$ uses $\sin\theta$ only?",
             feedback=[r"That is $2\sin\theta$. The formula is $1 - 2\sin^2\theta$, with the sine squared.", "", r"That is $\sin^2\theta$ on its own, not $\cos 2\theta$.",r"The sign is wrong: $1 - \frac{2}{9}$ is positive."]),
        QUIZ(r"How many solutions has $\sin 2x = \sin x$ for $0^\circ \leq x \leq 360^\circ$?",
             ["2", "3", "5", "4"], 2,
             r"The factors give $x = 0^\circ,\ 60^\circ,\ 180^\circ,\ 300^\circ,\ 360^\circ$: five solutions.",
             feedback=["That counts only the solutions of $\\cos x = \\frac{1}{2}$, so $\\sin x = 0$ was lost.", "That is $x = 0^\\circ,\\ 180^\\circ,\\ 360^\\circ$ only: $60^\\circ$ and $300^\\circ$ are solutions too.", "", "Check the end points: both $0^\\circ$ and $360^\\circ$ are in the range."]),
        H("Practice questions"),
        PQ(r"Prove that $\sin 3\theta \equiv 3\sin\theta - 4\sin^3\theta$.",
           r"$\sin 3\theta = \sin(2\theta + \theta) = \sin 2\theta\cos\theta + \cos 2\theta\sin\theta = 2\sin\theta\cos^2\theta + (1 - 2\sin^2\theta)\sin\theta$. Replace $\cos^2\theta = 1 - \sin^2\theta$: $= 2\sin\theta - 2\sin^3\theta + \sin\theta - 2\sin^3\theta = 3\sin\theta - 4\sin^3\theta$."),
        PQ(r"Solve $\cos 2x + 5\cos x = 2$ for $0^\circ \leq x \leq 360^\circ$.",
           r"$2\cos^2 x - 1 + 5\cos x - 2 = 0 \Rightarrow 2\cos^2 x + 5\cos x - 3 = 0 \Rightarrow (2\cos x - 1)(\cos x + 3) = 0$. $\cos x = -3$ has no solution. $\cos x = \frac{1}{2}$ gives $x = 60^\circ$ or $300^\circ$. Check $x = 60^\circ$: $\cos 120^\circ + 5\cos 60^\circ = -0.5 + 2.5 = 2$."),
        PQ(r"$A$ is obtuse and $\sin A = \frac{5}{13}$. Find the exact values of $\sin 2A$ and $\cos 2A$.",
           r"$A$ is obtuse, so $\cos A = -\frac{12}{13}$. $\sin 2A = 2\cdot\frac{5}{13}\cdot\left(-\frac{12}{13}\right) = -\frac{120}{169}$. $\cos 2A = 1 - 2\sin^2 A = 1 - \frac{50}{169} = \frac{119}{169}$. Check: $\left(\frac{120}{169}\right)^2 + \left(\frac{119}{169}\right)^2 = \frac{14400 + 14161}{28561} = 1$."),
        PQ(r"Show that $\displaystyle\int_0^{\pi/2}\cos^2 x\,dx = \frac{\pi}{4}$.",
           r"$\cos^2 x = \frac{1}{2}(1 + \cos 2x)$, so the integral is $\left[\frac{x}{2} + \frac{\sin 2x}{4}\right]_0^{\pi/2} = \left(\frac{\pi}{4} + 0\right) - 0 = \frac{\pi}{4}$."),
        TIP(r"Exam link: Paper 1 (multiple choice) tests the three forms of $\cos 2A$ and quick values like $\cos 2\theta$ from $\sin\theta$. In Paper 2 (Pure Mathematics) the formulae appear in proofs, equations and integrals of $\sin^2 x$ and $\cos^2 x$.", title="Exam link"),
        H("Summary"),
        SUM(r"$\sin 2A = 2\sin A\cos A$ and $\tan 2A = \dfrac{2\tan A}{1 - \tan^2 A}$.",
            r"$\cos 2A = \cos^2 A - \sin^2 A = 2\cos^2 A - 1 = 1 - 2\sin^2 A$: choose the form with one function.",
            r"$\cos^2 A = \frac{1}{2}(1 + \cos 2A)$ and $\sin^2 A = \frac{1}{2}(1 - \cos 2A)$ are used to integrate squares.",
            "Factorize instead of dividing by a trigonometric function, so no solutions are lost.",
            "When you solve for a multiple angle, write out the whole range of the multiple angle first."),
    ],
))

# ---------------------------------------------------------------- Identities: half angles and t-formulae
LESSONS.append(lesson(
    module=MODULE,
    topic="Identities",
    title="Half-angle and t-formulae",
    slug="pt-half-angle-and-t-formulae",
    minutes=22,
    summary="Use half-angle formulae for exact values and proofs, and the substitution t = tan(θ/2) to turn sin θ, cos θ and tan θ into algebra, taking care over the solution θ = 180°.",
    objectives=[
        "Write cos²(θ/2), sin²(θ/2) and tan(θ/2) in terms of cos θ and sin θ",
        "Find exact values such as sin 15° and tan 22.5°",
        "Use the t-formulae to solve equations of the form a sin θ + b cos θ = c",
        "Check separately for the solution that the substitution misses",
    ],
    key_concepts=["Half-angle formula", "t = tan(θ/2)", "t-formulae", "Exact value", "Lost solution at 180°"],
    blocks=[
        H("Introduction"),
        T(r"A tiler in Bamenda is laying octagonal floor tiles. Each corner of a regular octagon turns through $45^\circ$, and the line that cuts a corner in half makes an angle of $22.5^\circ$ with each side. The exact value of $\tan 22.5^\circ$ is a surd, and you can find it only with a **half-angle** formula."),
        T(r"The substitution $t = \tan\frac{\theta}{2}$ is also a powerful tool: it changes any equation in $\sin\theta$ and $\cos\theta$ into an ordinary algebraic equation in $t$. It is used again in integration."),
        H("Half-angle formulae"),
        D(r"These come from the double-angle formulae with $A = \frac{\theta}{2}$. They are true for all $\theta$.", title="Half angles",
          formula=r"\cos^2\tfrac{\theta}{2} = \tfrac{1}{2}(1 + \cos\theta), \qquad \sin^2\tfrac{\theta}{2} = \tfrac{1}{2}(1 - \cos\theta)",
          note=r"Taking a square root gives $\pm$. Choose the sign from the quadrant of $\frac{\theta}{2}$."),
        D(r"Divide $\sin\theta = 2\sin\frac{\theta}{2}\cos\frac{\theta}{2}$ by $1 + \cos\theta = 2\cos^2\frac{\theta}{2}$, or by $1 - \cos\theta = 2\sin^2\frac{\theta}{2}$.", title="Tangent of a half angle",
          formula=r"\tan\tfrac{\theta}{2} = \frac{\sin\theta}{1 + \cos\theta} = \frac{1 - \cos\theta}{\sin\theta}"),
        EX("Worked example 1: sin 15°", intro=r"Use a half-angle formula to find the exact value of $\sin 15^\circ$.", steps=[
            S("Write $15^\\circ$ as half of $30^\\circ$", math=r"\sin^2 15^\circ = \tfrac{1}{2}(1 - \cos 30^\circ)"),
            S("Substitute $\\cos 30^\\circ = \\frac{\\sqrt{3}}{2}$", math=r"= \tfrac{1}{2}\left(1 - \tfrac{\sqrt{3}}{2}\right) = \frac{2 - \sqrt{3}}{4}"),
            S("Take the positive root ($15^\\circ$ is acute)", math=r"\sin 15^\circ = \frac{\sqrt{2 - \sqrt{3}}}{2}"),
            S(r"This can be simplified: $\left(\frac{\sqrt{6} - \sqrt{2}}{4}\right)^2 = \frac{8 - 4\sqrt{3}}{16} = \frac{2 - \sqrt{3}}{4}$", math=r"\sin 15^\circ = \frac{\sqrt{6} - \sqrt{2}}{4}"),
        ], check=r"\frac{2.4495 - 1.4142}{4} = 0.2588 = \sin 15^\circ"),
        EX("Worked example 2: a proof", intro=r"Prove that $\dfrac{1 - \cos\theta}{1 + \cos\theta} \equiv \tan^2\dfrac{\theta}{2}$.", steps=[
            S("Top", math=r"1 - \cos\theta = 2\sin^2\tfrac{\theta}{2}"),
            S("Bottom", math=r"1 + \cos\theta = 2\cos^2\tfrac{\theta}{2}"),
            S("Divide", math=r"\frac{2\sin^2\frac{\theta}{2}}{2\cos^2\frac{\theta}{2}} = \tan^2\tfrac{\theta}{2}"),
        ]),
        H("The t-formulae"),
        D(r"Let $t = \tan\frac{\theta}{2}$. Then", title="t-formulae",
          formula=r"\sin\theta = \frac{2t}{1 + t^2}, \qquad \cos\theta = \frac{1 - t^2}{1 + t^2}, \qquad \tan\theta = \frac{2t}{1 - t^2}",
          note=r"Every right-hand side is an algebraic fraction in $t$. $\tan\theta$ is not defined when $t = \pm 1$."),
        T(r"**Where they come from.** Draw a right-angled triangle with sides $1$ and $t$ for the angle $\frac{\theta}{2}$. Its hypotenuse is $\sqrt{1 + t^2}$, so $\sin\frac{\theta}{2} = \frac{t}{\sqrt{1 + t^2}}$ and $\cos\frac{\theta}{2} = \frac{1}{\sqrt{1 + t^2}}$. Then $\sin\theta = 2\sin\frac{\theta}{2}\cos\frac{\theta}{2} = \frac{2t}{1 + t^2}$ and $\cos\theta = \cos^2\frac{\theta}{2} - \sin^2\frac{\theta}{2} = \frac{1 - t^2}{1 + t^2}$."),
        EX("Worked example 3: tan 22.5°", intro=r"Use the formula for $\tan\theta$ in terms of $t$ to find the exact value of $\tan 22.5^\circ$.", steps=[
            S(r"Let $\theta = 45^\circ$, so $t = \tan 22.5^\circ$ and $\tan 45^\circ = 1$", math=r"1 = \frac{2t}{1 - t^2}"),
            S("Rearrange into a quadratic", math=r"1 - t^2 = 2t \;\Rightarrow\; t^2 + 2t - 1 = 0"),
            S("Quadratic formula", math=r"t = \frac{-2 \pm \sqrt{8}}{2} = -1 \pm \sqrt{2}"),
            S("$22.5^\\circ$ is acute, so $t > 0$", math=r"\tan 22.5^\circ = \sqrt{2} - 1"),
        ], check=r"\sqrt{2} - 1 = 0.41421 = \tan 22.5^\circ"),
        EX("Worked example 4: an equation", solve=r"2\sin\theta - \cos\theta = 1, \quad 0^\circ \leq \theta \leq 360^\circ", steps=[
            S("Substitute the t-formulae", math=r"\frac{4t}{1 + t^2} - \frac{1 - t^2}{1 + t^2} = 1"),
            S("Multiply by $1 + t^2$", math=r"4t - 1 + t^2 = 1 + t^2"),
            S("The $t^2$ terms cancel", math=r"4t = 2 \;\Rightarrow\; t = \tfrac{1}{2}"),
            S(r"Solve $\tan\frac{\theta}{2} = \frac{1}{2}$. Here $0^\circ \leq \frac{\theta}{2} \leq 180^\circ$", math=r"\tfrac{\theta}{2} = 26.57^\circ \;\Rightarrow\; \theta = 53.13^\circ"),
            S(r"**Check $\theta = 180^\circ$ separately**, because $\tan 90^\circ$ does not exist", math=r"2\sin 180^\circ - \cos 180^\circ = 0 + 1 = 1 \quad \checkmark"),
            S("Answer", math=r"\theta = 53.1^\circ \text{ or } 180^\circ"),
        ], check=r"2\sin 53.13^\circ - \cos 53.13^\circ = 1.6 - 0.6 = 1"),
        MISTAKE(r"Missing $\theta = 180^\circ$", r"The t-substitution cannot produce $\theta = 180^\circ$ because $t = \tan 90^\circ$ is undefined. Always test $\theta = 180^\circ$ (or $\pi$) in the original equation if it is in the range. Notice what happened in the example above: the $t^2$ terms cancelled and left only one value of $t$. Whenever the $t^2$ terms cancel like this, the missing solution is $\theta = 180^\circ$."),
        H("A calculus link (radians)"),
        EX("Worked example 5: an integral", intro=r"Find $\displaystyle\int_0^{\pi/2}\frac{d\theta}{1 + \cos\theta}$.", steps=[
            S("Use $1 + \\cos\\theta = 2\\cos^2\\frac{\\theta}{2}$", math=r"\frac{1}{1 + \cos\theta} = \frac{1}{2}\sec^2\tfrac{\theta}{2}"),
            S(r"Integrate: $\int \sec^2(kx)\,dx = \frac{1}{k}\tan(kx)$, with $k = \frac{1}{2}$", math=r"\int \tfrac{1}{2}\sec^2\tfrac{\theta}{2}\,d\theta = \tan\tfrac{\theta}{2}"),
            S("Apply the limits", math=r"\tan\tfrac{\pi}{4} - \tan 0 = 1"),
        ], check=r"\text{numerical integration of } \frac{1}{1 + \cos\theta} \text{ on } [0, \tfrac{\pi}{2}] \text{ gives } 1.0000"),
        H("Common mistakes"),
        MISTAKE("Forgetting the ± or choosing the wrong sign", r"$\sin\frac{\theta}{2} = \pm\sqrt{\frac{1 - \cos\theta}{2}}$. Ask which quadrant $\frac{\theta}{2}$ is in. For $\theta = 300^\circ$, $\frac{\theta}{2} = 150^\circ$, so $\sin$ is positive but $\cos$ is negative."),
        MISTAKE("Using the wrong range for t", r"If $0^\circ \leq \theta \leq 360^\circ$ then $0^\circ \leq \frac{\theta}{2} \leq 180^\circ$. Solve $\tan\frac{\theta}{2} = t$ in that range, then double."),
        MISTAKE("Mixing up the two half-angle formulae", r"Remember: **minus** gives $\sin^2\frac{\theta}{2}$, **plus** gives $\cos^2\frac{\theta}{2}$. Check with $\theta = 0$: $\cos^2 0 = 1 = \frac{1}{2}(1 + 1)$."),
        QUIZ(r"Given $\cos\theta = \frac{3}{5}$ and $\theta$ acute, what is $\tan\frac{\theta}{2}$?",
             [r"$\frac{1}{2}$", r"$\frac{1}{4}$", r"$\frac{4}{3}$", r"$2$"], 0,
             r"$\tan^2\frac{\theta}{2} = \frac{1 - \cos\theta}{1 + \cos\theta} = \frac{2/5}{8/5} = \frac{1}{4}$, and $\frac{\theta}{2}$ is acute, so $\tan\frac{\theta}{2} = \frac{1}{2}$.",
             hint=r"Use $\tan^2\frac{\theta}{2} = \frac{1 - \cos\theta}{1 + \cos\theta}$.",
             feedback=["", r"That is $\tan^2\frac{\theta}{2}$. Take the square root.", r"That is $\tan\theta$, not $\tan\frac{\theta}{2}$.", r"You inverted the fraction: $\frac{1 + \cos\theta}{1 - \cos\theta} = 4$ and its root is $2$."]),
        QUIZ(r"With $t = \tan\frac{\theta}{2}$, which is $\cos\theta$?",
             [r"$\frac{2t}{1 + t^2}$", r"$\frac{1 + t^2}{1 - t^2}$", r"$\frac{1 - t^2}{1 + t^2}$", r"$\frac{2t}{1 - t^2}$"], 2,
             r"$\cos\theta = \frac{1 - t^2}{1 + t^2}$. Check $t = 0$ ($\theta = 0$): it gives $1$.",
             feedback=[r"That is $\sin\theta$.", r"At $t = 1$ ($\theta = 90^\circ$) this is undefined, but $\cos 90^\circ = 0$, so it cannot be $\cos\theta$.", "", r"That is $\tan\theta$."]),
        H("Practice questions"),
        PQ(r"Given that $\cos\theta = \frac{3}{5}$ and $\theta$ is acute, find the exact values of $\sin\frac{\theta}{2}$, $\cos\frac{\theta}{2}$ and $\tan\frac{\theta}{2}$.",
           r"$\sin^2\frac{\theta}{2} = \frac{1}{2}\left(1 - \frac{3}{5}\right) = \frac{1}{5}$, so $\sin\frac{\theta}{2} = \frac{1}{\sqrt{5}}$. $\cos^2\frac{\theta}{2} = \frac{1}{2}\left(1 + \frac{3}{5}\right) = \frac{4}{5}$, so $\cos\frac{\theta}{2} = \frac{2}{\sqrt{5}}$. Both are positive because $\frac{\theta}{2}$ is acute. $\tan\frac{\theta}{2} = \frac{1}{2}$."),
        PQ(r"Use $t = \tan\frac{\theta}{2}$ to solve $3\sin\theta - \cos\theta = 1$ for $0^\circ \leq \theta \leq 360^\circ$.",
           r"$\frac{6t}{1 + t^2} - \frac{1 - t^2}{1 + t^2} = 1 \Rightarrow 6t - 1 + t^2 = 1 + t^2 \Rightarrow t = \frac{1}{3}$. Then $\frac{\theta}{2} = 18.43^\circ$, so $\theta = 36.9^\circ$. Test $\theta = 180^\circ$: $3(0) - (-1) = 1$, which is true. So $\theta = 36.9^\circ$ or $180^\circ$."),
        PQ(r"Prove that $\dfrac{\sin\theta}{1 + \cos\theta} \equiv \tan\dfrac{\theta}{2}$.",
           r"$\sin\theta = 2\sin\frac{\theta}{2}\cos\frac{\theta}{2}$ and $1 + \cos\theta = 2\cos^2\frac{\theta}{2}$. So the fraction is $\frac{2\sin\frac{\theta}{2}\cos\frac{\theta}{2}}{2\cos^2\frac{\theta}{2}} = \frac{\sin\frac{\theta}{2}}{\cos\frac{\theta}{2}} = \tan\frac{\theta}{2}$."),
        PQ(r"Find the exact value of $\displaystyle\int_0^{\pi/3}\frac{d\theta}{1 + \cos\theta}$.",
           r"$\int\frac{d\theta}{1 + \cos\theta} = \tan\frac{\theta}{2}$, so the integral is $\tan\frac{\pi}{6} - \tan 0 = \frac{1}{\sqrt{3}} = \frac{\sqrt{3}}{3}$."),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for half-angle values and for the t-formulae by name. In Paper 2 (Pure Mathematics) the t-substitution solves $a\sin\theta + b\cos\theta = c$ and the answer must include the check at $\theta = 180^\circ$.", title="Exam link"),
        H("Summary"),
        SUM(r"$\cos^2\frac{\theta}{2} = \frac{1}{2}(1 + \cos\theta)$ and $\sin^2\frac{\theta}{2} = \frac{1}{2}(1 - \cos\theta)$; choose the sign from the quadrant.",
            r"$\tan\frac{\theta}{2} = \dfrac{\sin\theta}{1 + \cos\theta} = \dfrac{1 - \cos\theta}{\sin\theta}$.",
            r"With $t = \tan\frac{\theta}{2}$: $\sin\theta = \dfrac{2t}{1 + t^2}$, $\cos\theta = \dfrac{1 - t^2}{1 + t^2}$, $\tan\theta = \dfrac{2t}{1 - t^2}$.",
            r"Solve $\tan\frac{\theta}{2} = t$ in the range of $\frac{\theta}{2}$, then double.",
            r"Always test $\theta = 180^\circ$ separately: the substitution cannot find it."),
    ],
))

# ---------------------------------------------------------------- Identities: harmonic form
LESSONS.append(lesson(
    module=MODULE,
    topic="Identities",
    title="The harmonic form R cos(θ ± α)",
    slug="pt-harmonic-form-r-cos-theta-alpha",
    minutes=24,
    summary="Combine a cos θ + b sin θ into a single wave R cos(θ − α), R cos(θ + α), R sin(θ + α) or R sin(θ − α), then find maximum and minimum values, sketch it and solve equations.",
    objectives=[
        "Write a cos θ + b sin θ in any of the four forms R cos(θ ± α) and R sin(θ ± α)",
        "State the greatest and least values and where they occur",
        "Solve equations in degrees and in radians, adjusting the range for θ ± α",
        "Find the greatest and least values of expressions that contain a harmonic form",
    ],
    key_concepts=["Harmonic form", "Amplitude R", "Phase angle α", "Maximum and minimum", "Shifted range"],
    blocks=[
        H("Introduction"),
        T(r"In an alternating-current system, voltages from two sources with the same frequency add up. If one is $6\cos t$ and the other is $8\sin t$, their sum is $6\cos t + 8\sin t$. Remarkably, this sum is **one single wave** of the same frequency, $10\cos(t - 0.927)$. The same idea combines two sound waves, or two light signals."),
        T(r"Written as one wave, the sum shows its **amplitude** (the biggest value) at once, and equations become one-step problems."),
        IMG("apm-pt-harmonic-wave.svg", alt="Graph of 6 cos t, 8 sin t and their sum, a single wave of height 10 shifted right by about 0.93 radians", caption=r"Figure 1. The thin curves are $6\cos t$ and $8\sin t$. Their sum (thick) is $10\cos(t - 0.927)$: a cosine wave of amplitude 10, shifted to the right."),
        H("The method"),
        D(r"Expand $R\cos(\theta - \alpha) = R\cos\theta\cos\alpha + R\sin\theta\sin\alpha$ and match it with $a\cos\theta + b\sin\theta$.", title="Harmonic form",
          formula=r"a\cos\theta + b\sin\theta = R\cos(\theta - \alpha) \;\text{ where }\; R\cos\alpha = a,\quad R\sin\alpha = b,\quad R = \sqrt{a^2 + b^2},\quad \tan\alpha = \frac{b}{a}",
          note=r"Take $R > 0$ and $\alpha$ acute when $a$ and $b$ are both positive. In an exam question $\alpha$ is normally acute."),
        KEY("The four forms", r"Here $a$ and $b$ are positive. Always expand the form you are asked for and compare the coefficients of $\cos\theta$ and $\sin\theta$.", cards=[
            [r"$R\cos(\theta - \alpha)$", r"For $a\cos\theta + b\sin\theta$: $R\cos\alpha = a$ and $R\sin\alpha = b$"],
            [r"$R\cos(\theta + \alpha)$", r"For $a\cos\theta - b\sin\theta$: $R\cos\alpha = a$ and $R\sin\alpha = b$"],
            [r"$R\sin(\theta + \alpha)$", r"For $a\sin\theta + b\cos\theta$: $R\cos\alpha = a$ and $R\sin\alpha = b$"],
            [r"$R\sin(\theta - \alpha)$", r"For $a\sin\theta - b\cos\theta$: $R\cos\alpha = a$ and $R\sin\alpha = b$"],
        ]),
        D(r"Because $\cos(\theta - \alpha)$ goes between $-1$ and $1$:", title="Greatest and least values",
          formula=r"\text{greatest value } R \text{ (when } \theta = \alpha\text{)}, \qquad \text{least value } -R \text{ (when } \theta = \alpha + 180^\circ\text{)}"),
        EX("Worked example 1: R sin(θ + α)", intro=r"Express $5\sin\theta + 12\cos\theta$ in the form $R\sin(\theta + \alpha)$ with $R > 0$ and $0^\circ < \alpha < 90^\circ$. State the greatest value and where it occurs.", steps=[
            S("Expand the form", math=r"R\sin(\theta + \alpha) = R\cos\alpha\,\sin\theta + R\sin\alpha\,\cos\theta"),
            S("Compare coefficients", math=r"R\cos\alpha = 5, \qquad R\sin\alpha = 12"),
            S("Find $R$ and $\\alpha$", math=r"R = \sqrt{25 + 144} = 13, \qquad \tan\alpha = \tfrac{12}{5} \Rightarrow \alpha = 67.38^\circ"),
            S("Write the result", math=r"5\sin\theta + 12\cos\theta = 13\sin(\theta + 67.38^\circ)"),
            S(r"The greatest value is $13$, when $\sin(\theta + 67.38^\circ) = 1$", math=r"\theta + 67.38^\circ = 90^\circ \Rightarrow \theta = 22.62^\circ"),
        ], check=r"\theta = 22.62^\circ:\ 5(0.3846) + 12(0.9231) = 1.923 + 11.077 = 13.00"),
        EX("Worked example 2: an equation in degrees", solve=r"\sqrt{3}\cos\theta - \sin\theta = 1, \quad 0^\circ \leq \theta \leq 360^\circ", steps=[
            S("Use the form $R\\cos(\\theta + \\alpha)$. Expand it", math=r"R\cos\theta\cos\alpha - R\sin\theta\sin\alpha"),
            S("Compare", math=r"R\cos\alpha = \sqrt{3}, \qquad R\sin\alpha = 1"),
            S("Find $R$ and $\\alpha$", math=r"R = \sqrt{3 + 1} = 2, \qquad \tan\alpha = \tfrac{1}{\sqrt{3}} \Rightarrow \alpha = 30^\circ"),
            S("Rewrite the equation", math=r"2\cos(\theta + 30^\circ) = 1 \;\Rightarrow\; \cos(\theta + 30^\circ) = \tfrac{1}{2}"),
            S(r"The range of $\theta + 30^\circ$ is $30^\circ$ to $390^\circ$", math=r"\theta + 30^\circ = 60^\circ \text{ or } 300^\circ"),
            S("Answer", math=r"\theta = 30^\circ \text{ or } 270^\circ"),
        ], check=r"\theta = 270^\circ:\ \sqrt{3}\cdot 0 - (-1) = 1"),
        EX("Worked example 3: an equation in radians", solve=r"6\cos t + 8\sin t = 7, \quad 0 \leq t \leq 2\pi", steps=[
            S("Write as $R\\cos(t - \\alpha)$", math=r"R = \sqrt{36 + 64} = 10, \qquad \tan\alpha = \tfrac{8}{6} \Rightarrow \alpha = 0.9273 \text{ rad}"),
            S("Rewrite the equation", math=r"10\cos(t - 0.9273) = 7 \;\Rightarrow\; \cos(t - 0.9273) = 0.7"),
            S(r"The range of $t - 0.9273$ is $-0.9273$ to $5.3559$. The principal value is $\arccos 0.7 = 0.7954$", math=r"t - 0.9273 = 0.7954 \text{ or } -0.7954"),
            S(r"The value $2\pi - 0.7954 = 5.4878$ is **outside** the range, so it is not used", math=r"t = 1.7227 \text{ or } 0.1319"),
        ], check=r"6\cos 1.7227 + 8\sin 1.7227 = -0.908 + 7.908 \approx 7.000"),
        EX("Worked example 4: greatest and least values", intro=r"The electricity demand on a small local network is modelled by $L = 40 + 6\cos t + 8\sin t$ megawatts, where $t$ is an angle in radians. Find the greatest and least demand.", steps=[
            S("Write the wave part as one cosine", math=r"6\cos t + 8\sin t = 10\cos(t - 0.9273)"),
            S("It goes between $-10$ and $10$", math=r"30 \leq L \leq 50"),
            S("Greatest at $t = 0.9273$, least at $t = 0.9273 + \\pi$", math=r"L_{\max} = 50 \text{ MW}, \qquad L_{\min} = 30 \text{ MW} \text{ (at } t = 4.069\text{)}"),
        ], check=r"L(0.9273) = 40 + 6(0.6) + 8(0.8) = 50"),
        H("Common mistakes"),
        MISTAKE(r"Taking $R = a + b$", r"$R = \sqrt{a^2 + b^2}$. For $6\cos t + 8\sin t$, $R = 10$, not $14$. The two waves peak at different times, so they never add fully."),
        MISTAKE(r"Swapping $\sin\alpha$ and $\cos\alpha$", r"In $R\cos(\theta - \alpha)$ the coefficient of $\cos\theta$ is $R\cos\alpha$. In $R\sin(\theta + \alpha)$ the coefficient of $\sin\theta$ is $R\cos\alpha$. Expand your chosen form before you compare."),
        MISTAKE("Using the wrong range", r"When you solve for $\theta + 30^\circ$ the range moves to $30^\circ \leq \theta + 30^\circ \leq 390^\circ$. Write the new range down first, then find every angle in it."),
        MISTAKE("Mixing degrees and radians", r"If the range is given with $\pi$, work in radians throughout: calculator in radian mode, and $\alpha$ in radians."),
        QUIZ(r"Write $4\cos\theta + 3\sin\theta$ as $R\cos(\theta - \alpha)$. What are $R$ and $\alpha$?",
             [r"$R = 7$, $\alpha = 36.9^\circ$", r"$R = 5$, $\alpha = 53.1^\circ$", r"$R = 5$, $\alpha = 36.9^\circ$", r"$R = 25$, $\alpha = 36.9^\circ$"], 2,
             r"$R = \sqrt{16 + 9} = 5$, and $R\cos\alpha = 4$, $R\sin\alpha = 3$ give $\tan\alpha = \frac{3}{4}$, so $\alpha = 36.9^\circ$.",
             hint=r"Compare $R\cos\alpha$ with the coefficient of $\cos\theta$.",
             feedback=[r"You added 4 and 3. $R = \sqrt{a^2 + b^2}$.", r"You used $\tan\alpha = \frac{4}{3}$, the wrong way up. The sine goes with the coefficient of $\sin\theta$: $\tan\alpha = \frac{b}{a} = \frac{3}{4}$.", "", r"You forgot the square root: $25 = a^2 + b^2$."]),
        QUIZ(r"What is the least value of $3 - 8\cos\theta + 6\sin\theta$?",
             [r"$-11$", r"$-7$", r"$-5$", r"$-10$"], 1,
             r"$-8\cos\theta + 6\sin\theta$ has $R = 10$, so it goes from $-10$ to $10$. The least value of the whole expression is $3 - 10 = -7$.",
             feedback=[r"You added the coefficients: $3 - 14 = -11$. Use $R = \sqrt{64 + 36} = 10$.", "", r"You took $R = 8$, the larger coefficient. Use $\sqrt{a^2 + b^2}$.", r"$-10$ is the least value of the wave part alone. Add the constant $3$."]),
        H("Practice questions"),
        PQ(r"Express $12\sin x - 5\cos x$ in the form $R\sin(x - \alpha)$ with $R > 0$ and $0^\circ < \alpha < 90^\circ$. Hence solve $12\sin x - 5\cos x = 6.5$ for $0^\circ \leq x \leq 360^\circ$.",
           r"$R\sin(x - \alpha) = R\cos\alpha\sin x - R\sin\alpha\cos x$, so $R\cos\alpha = 12$ and $R\sin\alpha = 5$. $R = 13$ and $\alpha = \arctan\frac{5}{12} = 22.62^\circ$. Then $13\sin(x - 22.62^\circ) = 6.5$, so $\sin(x - 22.62^\circ) = 0.5$. The range of $x - 22.62^\circ$ is $-22.62^\circ$ to $337.38^\circ$, so $x - 22.62^\circ = 30^\circ$ or $150^\circ$, giving $x = 52.6^\circ$ or $172.6^\circ$ (1 d.p.)."),
        PQ(r"Express $8\cos x - 15\sin x$ in the form $R\cos(x + \alpha)$. Hence find its least value, the value of $x$ in $0^\circ \leq x \leq 360^\circ$ where it occurs, and solve $8\cos x - 15\sin x = 4$.",
           r"$R\cos x\cos\alpha - R\sin x\sin\alpha$: $R\cos\alpha = 8$, $R\sin\alpha = 15$, so $R = 17$ and $\alpha = 61.93^\circ$. The least value is $-17$, when $x + 61.93^\circ = 180^\circ$, so $x = 118.1^\circ$. For $17\cos(x + 61.93^\circ) = 4$: $\cos(x + 61.93^\circ) = \frac{4}{17}$, so $x + 61.93^\circ = 76.39^\circ$ or $283.61^\circ$, giving $x = 14.5^\circ$ or $221.7^\circ$."),
        PQ(r"Find the greatest and least values of $\dfrac{10}{6 + 3\sin x + 4\cos x}$.",
           r"$3\sin x + 4\cos x = 5\sin(x + \alpha)$ takes values from $-5$ to $5$, so the denominator goes from $1$ to $11$ (never zero). The fraction is greatest when the denominator is least: $\frac{10}{1} = 10$. It is least when the denominator is greatest: $\frac{10}{11}$."),
        PQ(r"Show that $\sin x + \cos x \equiv \sqrt{2}\sin(x + 45^\circ)$ and hence solve $\sin x + \cos x = 1$ for $0^\circ \leq x \leq 360^\circ$.",
           r"$\sqrt{2}\sin(x + 45^\circ) = \sqrt{2}\left(\sin x\cdot\frac{\sqrt{2}}{2} + \cos x\cdot\frac{\sqrt{2}}{2}\right) = \sin x + \cos x$. Then $\sin(x + 45^\circ) = \frac{1}{\sqrt{2}}$, with $x + 45^\circ$ between $45^\circ$ and $405^\circ$: $x + 45^\circ = 45^\circ,\ 135^\circ$ or $405^\circ$, so $x = 0^\circ,\ 90^\circ$ or $360^\circ$."),
        TIP(r"Exam link: Paper 1 (multiple choice) usually asks for $R$, $\alpha$ or a greatest or least value. In Paper 2 (Pure Mathematics) you express the sum as one wave and then solve an equation or find a maximum; the shifted range is where marks are lost.", title="Exam link"),
        H("Summary"),
        SUM(r"$a\cos\theta + b\sin\theta = R\cos(\theta - \alpha)$ with $R = \sqrt{a^2 + b^2}$ and $\tan\alpha = \frac{b}{a}$.",
            "Expand the form you are given and compare coefficients of cos and sin: do not memorize which goes where.",
            r"The greatest value is $R$ and the least is $-R$; add any constant that is in the expression.",
            r"To solve, divide by $R$, then list every angle in the shifted range for $\theta \pm \alpha$ before you subtract or add $\alpha$.",
            "Stay in radians when the range is in terms of π."),
    ],
))

# ---------------------------------------------------------------- Identities: solving equations
LESSONS.append(lesson(
    module=MODULE,
    topic="Identities",
    title="Solving trigonometric equations with identities",
    slug="pt-solving-trig-equations-with-identities",
    minutes=24,
    summary="Choose and combine compound-angle, double-angle and Pythagorean identities to reduce an equation to one function of one angle, factorize, and list every solution in the range without losing any.",
    objectives=[
        "Reduce an equation to one trigonometric function of one angle using an identity",
        "Factorize instead of cancelling, so that no solutions are lost",
        "List all solutions of equations with multiple angles and shifted angles in the given range",
        "Solve equations in degrees and in radians and check the answers",
    ],
    key_concepts=["Strategy for equations", "Pythagorean identities", "Factorize, do not cancel", "Multiple angle range", "Checking solutions"],
    blocks=[
        H("Introduction"),
        T(r"Solving a trigonometric equation is like solving a puzzle with a short list of moves: use an identity to make the equation simpler, factorize, solve the simple parts, and check the range. Engineers meet these equations when they find the times at which a vibrating machine part, such as a pump in a water station, passes through a given position."),
        T(r"This lesson brings the identities of the earlier lessons together. The three **Pythagorean identities** are also needed:"),
        F(r"\sin^2\theta + \cos^2\theta = 1, \qquad 1 + \tan^2\theta = \sec^2\theta, \qquad 1 + \cot^2\theta = \operatorname{cosec}^2\theta"),
        H("A strategy"),
        KEY("Four steps", "Follow them in order each time.", cards=[
            ["1. One angle", r"Make every angle the same, using $\sin 2x$, $\cos 2x$, $\sin(x + a)$ and similar expansions."],
            ["2. One function", r"Use $\sin^2 + \cos^2 = 1$ or $\sec^2 = 1 + \tan^2$ so that only one function is left."],
            ["3. Factorize", r"Get $0$ on one side and factorize. Never cancel a factor that could be zero."],
            ["4. Range and check", "Write the range for the angle you solve for, list all values in it, then check in the original equation."],
        ]),
        H("Worked examples"),
        EX("Worked example 1: sin² and cos² together", solve=r"2\cos^2 x + 3\sin x = 3, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Replace $\\cos^2 x$ so that only $\\sin x$ remains", math=r"2(1 - \sin^2 x) + 3\sin x = 3"),
            S("Rearrange to zero", math=r"2\sin^2 x - 3\sin x + 1 = 0"),
            S("Factorize", math=r"(2\sin x - 1)(\sin x - 1) = 0"),
            S("Solve", math=r"\sin x = \tfrac{1}{2} \Rightarrow x = 30^\circ,\ 150^\circ; \qquad \sin x = 1 \Rightarrow x = 90^\circ"),
        ], check=r"x = 150^\circ:\ 2\cos^2 150^\circ + 3\sin 150^\circ = 2(0.75) + 1.5 = 3"),
        EX("Worked example 2: tan 2x", solve=r"\tan 2x = 3\tan x, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Let $t = \\tan x$ and use the double-angle formula", math=r"\frac{2t}{1 - t^2} = 3t"),
            S("Multiply by $1 - t^2$ and move everything to one side", math=r"2t - 3t(1 - t^2) = 0 \;\Rightarrow\; t(3t^2 - 1) = 0"),
            S("Solve for $t$", math=r"t = 0 \quad \text{or} \quad t = \pm\tfrac{1}{\sqrt{3}}"),
            S("Convert to $x$ in the range", math=r"\tan x = 0: x = 0^\circ,\ 180^\circ,\ 360^\circ \qquad \tan x = \pm\tfrac{1}{\sqrt{3}}: x = 30^\circ,\ 150^\circ,\ 210^\circ,\ 330^\circ"),
        ], check=r"x = 30^\circ:\ \tan 60^\circ = 1.732 = 3\tan 30^\circ"),
        EX("Worked example 3: a shifted angle", solve=r"\cos(x + 45^\circ) = \sin x, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Expand the left side", math=r"\tfrac{\sqrt{2}}{2}\cos x - \tfrac{\sqrt{2}}{2}\sin x = \sin x"),
            S("Collect the sines", math=r"\tfrac{\sqrt{2}}{2}\cos x = \left(1 + \tfrac{\sqrt{2}}{2}\right)\sin x"),
            S(r"Divide by $\cos x$ (this is safe: if $\cos x = 0$ then $\sin x = \pm 1$, and the equation would say $\mp\frac{\sqrt{2}}{2} = \pm 1$, which is false)", math=r"\tan x = \frac{\sqrt{2}/2}{1 + \sqrt{2}/2} = \frac{\sqrt{2}}{2 + \sqrt{2}} = \sqrt{2} - 1"),
            S("Solve", math=r"x = 22.5^\circ \text{ or } 202.5^\circ"),
        ], check=r"\cos 67.5^\circ = 0.3827 = \sin 22.5^\circ"),
        EX("Worked example 4: a multiple angle, in radians", solve=r"3\sin 2\theta = 2\cos\theta, \quad 0 \leq \theta \leq 2\pi", steps=[
            S("Use $\\sin 2\\theta = 2\\sin\\theta\\cos\\theta$", math=r"6\sin\theta\cos\theta = 2\cos\theta"),
            S("Factorize (do **not** divide by $\\cos\\theta$)", math=r"2\cos\theta\,(3\sin\theta - 1) = 0"),
            S("Case 1", math=r"\cos\theta = 0 \;\Rightarrow\; \theta = \tfrac{\pi}{2},\ \tfrac{3\pi}{2}"),
            S("Case 2", math=r"\sin\theta = \tfrac{1}{3} \;\Rightarrow\; \theta = 0.3398 \text{ or } \pi - 0.3398 = 2.8018"),
        ], check=r"\theta = 0.3398:\ 3\sin 0.6797 = 1.8856 = 2\cos 0.3398"),
        EX("Worked example 5: using the Pythagorean identity for tan", solve=r"\sec^2 x = 3\tan x - 1, \quad 0^\circ \leq x \leq 360^\circ", steps=[
            S("Use $\\sec^2 x = 1 + \\tan^2 x$", math=r"1 + \tan^2 x = 3\tan x - 1"),
            S("Rearrange", math=r"\tan^2 x - 3\tan x + 2 = 0 \;\Rightarrow\; (\tan x - 1)(\tan x - 2) = 0"),
            S(r"$\tan x = 1$", math=r"x = 45^\circ,\ 225^\circ"),
            S(r"$\tan x = 2$", math=r"x = 63.4^\circ,\ 243.4^\circ \ (1\text{ d.p.})"),
        ], check=r"x = 63.43^\circ:\ \sec^2 = 1 + 4 = 5 = 3(2) - 1"),
        H("Common mistakes"),
        MISTAKE("Cancelling a trigonometric factor", r"Dividing $3\sin 2\theta = 2\cos\theta$ by $\cos\theta$ loses $\theta = \frac{\pi}{2}$ and $\frac{3\pi}{2}$. Move everything to one side and factorize."),
        MISTAKE("Forgetting the other quadrants", r"$\sin x = \frac{1}{2}$ has two solutions in $0^\circ$ to $360^\circ$, $\tan x = k$ has two, and $\cos x = k$ has two. Check the sign of the function in each quadrant."),
        MISTAKE("Wrong range for a multiple angle", r"For $\sin 2x = 0.5$ with $0^\circ \leq x \leq 360^\circ$, list $2x = 30^\circ,\ 150^\circ,\ 390^\circ,\ 510^\circ$ and then halve: four solutions, not two."),
        MISTAKE("Not checking", r"Squaring or multiplying can add false solutions. A quick substitution into the original equation catches them."),
        QUIZ(r"How many solutions has $\sin 2x = 0.5$ for $0^\circ \leq x \leq 360^\circ$?",
             ["2", "3", "4", "8"], 2,
             r"$2x = 30^\circ,\ 150^\circ,\ 390^\circ,\ 510^\circ$ (the range of $2x$ is $0^\circ$ to $720^\circ$), so $x = 15^\circ,\ 75^\circ,\ 195^\circ,\ 255^\circ$.",
             hint=r"What is the range of $2x$?",
             feedback=["That is the number of solutions of $\\sin x = 0.5$. The range of $2x$ is twice as long.", "Count again: each full turn of $2x$ gives two solutions, and $2x$ turns twice.", "", "Too many: $\\sin 2x = 0.5$ gives two values per turn of $2x$, and there are two turns."]),
        QUIZ(r"To solve $\tan x = 2\sin x$ a student divides by $\sin x$ and gets $\cos x = \frac{1}{2}$, so $x = 60^\circ,\ 300^\circ$. Which solutions in $0^\circ \leq x \leq 360^\circ$ were lost?",
             [r"None", r"$x = 0^\circ,\ 180^\circ,\ 360^\circ$", r"$x = 90^\circ,\ 270^\circ$", r"$x = 30^\circ,\ 150^\circ$"], 1,
             r"$\frac{\sin x}{\cos x} - 2\sin x = 0 \Rightarrow \sin x(1 - 2\cos x) = 0$. The factor $\sin x = 0$ gives $x = 0^\circ,\ 180^\circ,\ 360^\circ$.",
             feedback=["Dividing by $\\sin x$ is exactly what loses the solutions where $\\sin x = 0$.", "", "At $90^\\circ$ and $270^\\circ$, $\\tan x$ is undefined, so they are not solutions.", "These do not satisfy the equation: $\\tan 30^\\circ = 0.577$ but $2\\sin 30^\\circ = 1$."]),
        H("Practice questions"),
        PQ(r"Solve $2\sin^2 x = 1 + \cos x$ for $0^\circ \leq x \leq 360^\circ$.",
           r"$2(1 - \cos^2 x) = 1 + \cos x \Rightarrow 2\cos^2 x + \cos x - 1 = 0 \Rightarrow (2\cos x - 1)(\cos x + 1) = 0$. $\cos x = \frac{1}{2}$ gives $x = 60^\circ,\ 300^\circ$; $\cos x = -1$ gives $x = 180^\circ$. Check $x = 180^\circ$: $0 = 1 + (-1)$."),
        PQ(r"Solve $\sin 2x = 3\sin^2 x$ for $0^\circ \leq x \leq 360^\circ$, giving non-exact answers to 1 decimal place.",
           r"$2\sin x\cos x - 3\sin^2 x = 0 \Rightarrow \sin x(2\cos x - 3\sin x) = 0$. $\sin x = 0$ gives $x = 0^\circ,\ 180^\circ,\ 360^\circ$. $2\cos x = 3\sin x$ gives $\tan x = \frac{2}{3}$, so $x = 33.7^\circ$ or $213.7^\circ$."),
        PQ(r"Solve $\cos 2\theta + 3\sin\theta = 2$ for $0 \leq \theta \leq 2\pi$, in radians.",
           r"$1 - 2\sin^2\theta + 3\sin\theta = 2 \Rightarrow 2\sin^2\theta - 3\sin\theta + 1 = 0 \Rightarrow (2\sin\theta - 1)(\sin\theta - 1) = 0$. $\sin\theta = \frac{1}{2}$: $\theta = \frac{\pi}{6},\ \frac{5\pi}{6}$. $\sin\theta = 1$: $\theta = \frac{\pi}{2}$."),
        PQ(r"Solve $4\sin x\cos x = 1$ for $0^\circ \leq x \leq 360^\circ$.",
           r"$2\sin 2x = 1$, so $\sin 2x = \frac{1}{2}$. The range of $2x$ is $0^\circ$ to $720^\circ$: $2x = 30^\circ,\ 150^\circ,\ 390^\circ,\ 510^\circ$. So $x = 15^\circ,\ 75^\circ,\ 195^\circ,\ 255^\circ$."),
        TIP(r"Exam link: Paper 1 (multiple choice) tests how many solutions an equation has or which solution is missing. In Paper 2 (Pure Mathematics), equations of this kind are worth full marks only if all the solutions in the range are given and the factorization is shown.", title="Exam link"),
        H("Summary"),
        SUM("Use identities to make one angle and one function, move everything to one side and factorize.",
            r"Useful identities: $\sin 2x = 2\sin x\cos x$, $\cos 2x$ in three forms, $\sec^2 x = 1 + \tan^2 x$, and the compound-angle expansions.",
            "Never divide by a trigonometric function that can be zero.",
            "For $2x$, $x + a$ and similar, write the full range of that angle before listing solutions.",
            "Check at least one solution in the original equation."),
    ],
))

# ---------------------------------------------------------------- Conic sections: circles and tangents
LESSONS.append(lesson(
    module=MODULE,
    topic="Conic sections",
    title="Circles, lines and tangents",
    slug="pt-circles-and-tangents",
    minutes=24,
    summary="Find the centre and radius of a circle, find a circle from given points, decide whether a line cuts, touches or misses it, and find tangents, chords and tangent lengths.",
    objectives=[
        "Write a circle in standard and general form and find its centre and radius",
        "Find the equation of a circle from three points or from a diameter",
        "Use the discriminant to decide whether a line cuts, touches or misses a circle, and find tangents",
        "Find the length of a tangent from an outside point, the length of a chord, and how two circles meet",
    ],
    key_concepts=["Circle equation", "Completing the square", "Tangent", "Discriminant", "Chord", "Tangent length", "Touching circles"],
    blocks=[
        H("Introduction"),
        T(r"A radio mast in Bafoussam covers every point within 20 km. The edge of the covered region is a circle. A straight road that just touches the edge is a **tangent**; a road that cuts across it is a **secant**, and the piece inside is a **chord**." "\n\n" r"The circle is the simplest conic section. This lesson shows how to work with its equation, how a line meets it, and how to find tangents. The ideas carry straight over to parabolas, ellipses and hyperbolas."),
        H("The equation of a circle"),
        D(r"A circle with centre $(a, b)$ and radius $r$ is the set of points at distance $r$ from the centre.", title="Standard and general forms",
          formula=r"(x - a)^2 + (y - b)^2 = r^2 \qquad\Longleftrightarrow\qquad x^2 + y^2 + 2gx + 2fy + c = 0",
          note=r"In the general form the centre is $(-g, -f)$ and $r^2 = g^2 + f^2 - c$. The equation is a circle only if $g^2 + f^2 - c > 0$." "\n\n" r"**Parametric form.** The point $(a + r\cos t,\ b + r\sin t)$ lies on the circle for every value of $t$. As $t$ goes from $0$ to $2\pi$ the point goes once round." "\n\n" r"**A circle on a diameter.** If $A(x_1, y_1)$ and $B(x_2, y_2)$ are the ends of a diameter, then every point $P$ on the circle gives a right angle at $P$ (the angle in a semicircle). That gives the neat equation $(x - x_1)(x - x_2) + (y - y_1)(y - y_2) = 0$."),
        EX("Worked example 1: centre and radius", intro=r"Find the centre and radius of the circle $x^2 + y^2 + 8x - 2y - 8 = 0$.", steps=[
            S("Group the $x$ terms and the $y$ terms", math=r"(x^2 + 8x) + (y^2 - 2y) = 8"),
            S("Complete the square in each", math=r"(x + 4)^2 - 16 + (y - 1)^2 - 1 = 8"),
            S("Move the constants to the right", math=r"(x + 4)^2 + (y - 1)^2 = 25"),
            S("Read off", math=r"\text{centre } (-4, 1), \qquad r = 5"),
        ], check=r"g = 4,\ f = -1,\ c = -8:\ r^2 = 16 + 1 + 8 = 25"),
        EX("Worked example 2: a circle through three points", intro=r"Find the equation of the circle through $A(5, 5)$, $B(-1, -3)$ and $C(6, -2)$.", steps=[
            S("Use the general form and substitute each point", math=r"\begin{aligned}50 + 10g + 10f + c &= 0\\ 10 - 2g - 6f + c &= 0\\ 40 + 12g - 4f + c &= 0\end{aligned}"),
            S("Subtract the second equation from the first, then the third from the first", math=r"40 + 12g + 16f = 0, \qquad 10 - 2g + 14f = 0"),
            S("Simplify and solve: $10 + 3g + 4f = 0$ and $5 - g + 7f = 0$", math=r"g = -2, \qquad f = -1"),
            S("Find $c$ from the first equation", math=r"50 - 20 - 10 + c = 0 \;\Rightarrow\; c = -20"),
            S("Write the equation", math=r"x^2 + y^2 - 4x - 2y - 20 = 0"),
        ], check=r"\text{centre } (2, 1),\ r^2 = 4 + 1 + 20 = 25.\quad B: 1 + 9 + 4 + 6 - 20 = 0\ \checkmark"),
        H("A line and a circle"),
        D(r"Substitute the equation of the line into the equation of the circle to get a quadratic. Its discriminant $b^2 - 4ac$ tells you how the line meets the circle.", title="Cut, touch or miss",
          formula=r"b^2 - 4ac > 0:\ \text{two points (a chord)} \qquad b^2 - 4ac = 0:\ \text{tangent} \qquad b^2 - 4ac < 0:\ \text{no intersection}"),
        EX("Worked example 3: finding tangents", intro=r"Find the values of $k$ for which the line $y = x + k$ is a tangent to the circle $x^2 + y^2 = 8$.", steps=[
            S("Substitute $y = x + k$", math=r"x^2 + (x + k)^2 = 8 \;\Rightarrow\; 2x^2 + 2kx + k^2 - 8 = 0"),
            S("A tangent means equal roots, so the discriminant is $0$", math=r"(2k)^2 - 4(2)(k^2 - 8) = 0"),
            S("Simplify", math=r"4k^2 - 8k^2 + 64 = 0 \;\Rightarrow\; k^2 = 16"),
            S("Solve", math=r"k = 4 \text{ or } k = -4"),
        ], check=r"\text{distance from } (0, 0) \text{ to } x - y + 4 = 0 \text{ is } \tfrac{4}{\sqrt{2}} = 2\sqrt{2} = r"),
        IMG("apm-pt-circle-tangent.svg", alt="Circle with centre C(2, 1) and radius 5, with a tangent line touching it at P(5, 5), perpendicular to the radius CP", caption=r"Figure 1. The tangent at $P$ is perpendicular to the radius $CP$. Radius gradient $\frac{4}{3}$, tangent gradient $-\frac{3}{4}$."),
        EX("Worked example 4: tangent at a point", intro=r"Find the tangent and the normal to the circle $(x - 2)^2 + (y - 1)^2 = 25$ at $P(5, 5)$.", steps=[
            S("Check that $P$ is on the circle", math=r"3^2 + 4^2 = 25 \quad\checkmark"),
            S("Gradient of the radius $CP$, with $C(2, 1)$", math=r"m = \frac{5 - 1}{5 - 2} = \frac{4}{3}"),
            S("The tangent is perpendicular to the radius", math=r"m_{\text{tangent}} = -\frac{3}{4}"),
            S("Tangent", math=r"y - 5 = -\tfrac{3}{4}(x - 5) \;\Rightarrow\; 3x + 4y = 35"),
            S("The normal passes through the centre, with gradient $\\frac{4}{3}$", math=r"y - 5 = \tfrac{4}{3}(x - 5) \;\Rightarrow\; 4x - 3y = 5"),
        ], check=r"\text{tangent: } 3(5) + 4(5) = 35.\quad \text{normal: } 4(5) - 3(5) = 5 \text{ and the centre } 4(2) - 3(1) = 5"),
        H("Tangent lengths, chords and two circles"),
        D(r"If $P$ is outside a circle with centre $C$ and radius $r$, and $T$ is a point where a tangent from $P$ touches the circle, then $CT \perp PT$, so by Pythagoras:", title="Length of a tangent",
          formula=r"PT^2 = PC^2 - r^2"),
        EX("Worked example 5: tangent length", intro=r"Find the length of a tangent from $P(10, 7)$ to the circle $x^2 + y^2 - 4x - 2y - 4 = 0$.", steps=[
            S("Centre and radius", math=r"g = -2,\ f = -1,\ c = -4:\ C(2, 1),\quad r^2 = 4 + 1 + 4 = 9"),
            S("Distance squared from $P$ to the centre", math=r"PC^2 = (10 - 2)^2 + (7 - 1)^2 = 100"),
            S("Apply the formula", math=r"PT^2 = 100 - 9 = 91 \;\Rightarrow\; PT = \sqrt{91} \approx 9.54"),
        ]),
        EX("Worked example 6: a chord", intro=r"The line $y = x + 1$ meets the circle $x^2 + y^2 = 13$ at $A$ and $B$. Find the length of the chord $AB$.", steps=[
            S("Substitute", math=r"x^2 + (x + 1)^2 = 13 \;\Rightarrow\; x^2 + x - 6 = 0"),
            S("Factorize and solve", math=r"(x + 3)(x - 2) = 0 \;\Rightarrow\; x = -3 \text{ or } 2"),
            S("Find the points", math=r"A(-3, -2), \qquad B(2, 3)"),
            S("Distance", math=r"AB = \sqrt{5^2 + 5^2} = 5\sqrt{2}"),
        ], check=r"\text{midpoint } (-\tfrac{1}{2}, \tfrac{1}{2}),\ \text{distance from } O = \tfrac{\sqrt{2}}{2}:\ \left(\tfrac{5\sqrt{2}}{2}\right)^2 + \tfrac{1}{2} = 13 = r^2"),
        KEY("Two circles with centres a distance d apart", r"Compare $d$ with $r_1 + r_2$ and $|r_1 - r_2|$.", cards=[
            ["Touch externally", r"$d = r_1 + r_2$. Example: centres $(0, 0)$ and $(8, 6)$, both radius 5, touch at $(4, 3)$."],
            ["Touch internally", r"$d = |r_1 - r_2|$. Example: $x^2 + y^2 = 100$ and a circle of radius 5 at $(3, 4)$ touch at $(6, 8)$."],
            ["Intersect at two points", r"$|r_1 - r_2| < d < r_1 + r_2$."],
            ["Do not meet", r"$d > r_1 + r_2$ (apart) or $d < |r_1 - r_2|$ (one inside the other)."],
        ]),
        H("Common mistakes"),
        MISTAKE("Wrong sign for the centre", r"$(x + 4)^2 + (y - 1)^2 = 25$ has centre $(-4, 1)$. The centre is the point that makes each bracket zero. In the general form the centre is $(-g, -f)$."),
        MISTAKE(r"Using $r^2$ as the radius", r"The right-hand side is $r^2$. For $(x - 1)^2 + (y - 2)^2 = 16$ the radius is $4$, not $16$. In the general form, $r^2 = g^2 + f^2 - c$."),
        MISTAKE("Using the radius gradient for the tangent", r"The tangent is **perpendicular** to the radius. If the radius has gradient $m$, the tangent has gradient $-\frac{1}{m}$."),
        QUIZ(r"What are the centre and radius of $x^2 + y^2 - 6x + 10y + 9 = 0$?",
             [r"Centre $(3, -5)$, radius $5$", r"Centre $(-3, 5)$, radius $5$", r"Centre $(3, -5)$, radius $25$", r"Centre $(6, -10)$, radius $\sqrt{9}$"], 0,
             r"$g = -3$, $f = 5$, so the centre is $(3, -5)$. $r^2 = 9 + 25 - 9 = 25$, so $r = 5$.",
             hint=r"Centre is $(-g, -f)$ and $r^2 = g^2 + f^2 - c$.",
             feedback=["", r"You used $(g, f)$. The centre is $(-g, -f)$.", r"$25$ is $r^2$. The radius is its square root.", r"The coefficients $-6$ and $10$ are $2g$ and $2f$, so halve them. Also $r^2 = g^2 + f^2 - c$, not $c$."]),
        QUIZ(r"Substituting a line into a circle gives $x^2 - 4x + 7 = 0$. What does this tell you?",
             ["The line is a tangent", "The line cuts the circle at two points", "The line misses the circle", "The line passes through the centre"], 2,
             r"$b^2 - 4ac = 16 - 28 = -12 < 0$, so there are no real intersection points: the line misses the circle.",
             feedback=[r"A tangent needs discriminant $0$.", r"Two points needs a positive discriminant.", "", "The discriminant gives no information about the centre; check by substituting the centre into the line."]),
        H("Practice questions"),
        PQ(r"$A(-1, 2)$ and $B(5, -6)$ are the ends of a diameter of a circle. Find its equation in the form $x^2 + y^2 + 2gx + 2fy + c = 0$, and write down the centre and the radius.",
           r"$(x + 1)(x - 5) + (y - 2)(y + 6) = 0 \Rightarrow x^2 - 4x - 5 + y^2 + 4y - 12 = 0 \Rightarrow x^2 + y^2 - 4x + 4y - 17 = 0$. Centre $(2, -2)$ (the midpoint of $AB$). $r^2 = 4 + 4 + 17 = 25$, so $r = 5$. Check: $AB = \sqrt{36 + 64} = 10 = 2r$."),
        PQ(r"Find the values of $k$ for which the line $y = 2x + k$ is a tangent to the circle $x^2 + y^2 = 20$.",
           r"$x^2 + (2x + k)^2 = 20 \Rightarrow 5x^2 + 4kx + k^2 - 20 = 0$. Discriminant $= 16k^2 - 20(k^2 - 20) = 400 - 4k^2 = 0$, so $k^2 = 100$ and $k = \pm 10$. Check: the distance from the origin to $2x - y + 10 = 0$ is $\frac{10}{\sqrt{5}} = 2\sqrt{5} = \sqrt{20}$."),
        PQ(r"The circle $x^2 + y^2 - 6x + 2y - 15 = 0$ passes through $P(6, 3)$. Find the equations of the tangent and the normal at $P$.",
           r"$g = -3$, $f = 1$, so the centre is $C(3, -1)$ and $r^2 = 9 + 1 + 15 = 25$. Check $P$: $36 + 9 - 36 + 6 - 15 = 0$. Gradient $CP = \frac{3 + 1}{6 - 3} = \frac{4}{3}$. The tangent has gradient $-\frac{3}{4}$: $y - 3 = -\frac{3}{4}(x - 6)$, so $3x + 4y = 30$. The normal is the line $CP$: $y - 3 = \frac{4}{3}(x - 6)$, so $4x - 3y = 15$."),
        PQ(r"Show that the circles $x^2 + y^2 = 25$ and $(x - 8)^2 + (y - 6)^2 = 25$ touch, and find the point of contact.",
           r"The centres are $(0, 0)$ and $(8, 6)$, and the distance between them is $\sqrt{64 + 36} = 10$. This equals $r_1 + r_2 = 5 + 5$, so the circles touch externally. The point of contact is the midpoint of the centres (equal radii): $(4, 3)$. Check: $16 + 9 = 25$ and $(4 - 8)^2 + (3 - 6)^2 = 25$."),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for the centre and radius, or whether a line cuts a circle. In Paper 2 (Pure Mathematics) you complete the square, use the discriminant for tangents and use the perpendicular radius for tangent equations.", title="Exam link"),
        H("Summary"),
        SUM(r"$(x - a)^2 + (y - b)^2 = r^2$; in $x^2 + y^2 + 2gx + 2fy + c = 0$ the centre is $(-g, -f)$ and $r^2 = g^2 + f^2 - c$.",
            "Find a circle from three points by substituting into the general form, or from a diameter with $(x - x_1)(x - x_2) + (y - y_1)(y - y_2) = 0$.",
            r"Substitute a line into the circle: discriminant $> 0$ cuts, $= 0$ tangent, $< 0$ misses.",
            "The tangent at a point is perpendicular to the radius; the normal passes through the centre.",
            r"Tangent length: $PT^2 = PC^2 - r^2$. Two circles touch when $d = r_1 + r_2$ or $d = |r_1 - r_2|$."),
    ],
))

# ---------------------------------------------------------------- Conic sections: parabolas
LESSONS.append(lesson(
    module=MODULE,
    topic="Conic sections",
    title="Parabolas: cartesian and parametric forms",
    slug="pt-parabolas-cartesian-and-parametric",
    minutes=24,
    summary="Use the focus-directrix definition, the equations y² = 4ax and (y − k)² = 4a(x − h), the parametric form (at², 2at), chords, focal chords and the tangent condition.",
    objectives=[
        "Use the focus and directrix to derive and apply y² = 4ax and its translations",
        "Find the vertex, focus and directrix of a parabola from its equation",
        "Use the parametric form (at², 2at) for points, chords and focal chords",
        "Find the condition for a line to touch a parabola",
    ],
    key_concepts=["Focus and directrix", "y² = 4ax", "Vertex form", "Parametric form (at², 2at)", "Focal chord", "Latus rectum"],
    blocks=[
        H("Introduction"),
        T(r"A satellite dish, a solar cooker and a car headlamp reflector all have the shape of a **parabola** turned about its axis. Every ray that arrives parallel to the axis bounces to **one point**, the focus. That is why the receiver of a dish sits at a particular distance in front of the middle." "\n\n" r"In this lesson you meet the equations of the parabola and the parametric form $(at^2, 2at)$ that makes chords and tangents easy."),
        H("Definition and equation"),
        D(r"A **parabola** is the set of points $P$ whose distance from a fixed point $F$ (the **focus**) equals its distance from a fixed line (the **directrix**). Its eccentricity is $e = 1$.", title="Parabola"),
        F(r"\sqrt{(x - a)^2 + y^2} = x + a \;\Rightarrow\; (x - a)^2 + y^2 = (x + a)^2 \;\Rightarrow\; y^2 = 4ax", title="Deriving y² = 4ax from the focus (a, 0) and the directrix x = −a: PF equals the distance to the directrix"),
        KEY("Standard forms (a > 0)", r"The vertex is the point of the curve closest to the directrix. Replace $x$ by $x - h$ and $y$ by $y - k$ to move the vertex to $(h, k)$.", cards=[
            [r"$y^2 = 4ax$", r"Opens right. Vertex $(0, 0)$, focus $(a, 0)$, directrix $x = -a$. Parametric: $(at^2, 2at)$."],
            [r"$y^2 = -4ax$", r"Opens left. Focus $(-a, 0)$, directrix $x = a$."],
            [r"$x^2 = 4ay$", r"Opens up. Focus $(0, a)$, directrix $y = -a$. Parametric: $(2at, at^2)$."],
            [r"$(y - k)^2 = 4a(x - h)$", r"Vertex $(h, k)$, focus $(h + a, k)$, directrix $x = h - a$."],
        ], note=r"The **latus rectum** is the chord through the focus, perpendicular to the axis. In $y^2 = 4ax$, put $x = a$: $y^2 = 4a^2$, so $y = \pm 2a$ and the latus rectum has length $4a$."),
        IMG("apm-pt-parabola-focus.svg", alt="The parabola y squared equals 8x with its focus at (2, 0), directrix x equals minus 2, and a point P whose distances PF and PM to the focus and the directrix are equal", caption=r"Figure 1. For the parabola $y^2 = 8x$ ($a = 2$): the point $P(4.5, 6)$ is $6.5$ from the focus and $6.5$ from the directrix."),
        EX("Worked example 1: a satellite dish", intro=r"A dish is $1.2\ \text{m}$ wide across its rim and $0.18\ \text{m}$ deep. Take the vertex as the origin and the axis along the $x$-axis. Find the distance from the vertex to the focus.", steps=[
            S("The curve is $y^2 = 4ax$. The rim point is at half-width $0.6$ and depth $0.18$", math=r"y = 0.6, \qquad x = 0.18"),
            S("Substitute", math=r"0.6^2 = 4a(0.18) \;\Rightarrow\; 0.36 = 0.72a"),
            S("Solve", math=r"a = 0.5"),
        ], check=r"y^2 = 2x:\ 0.36 = 2(0.18). \text{ The receiver is } 0.5\ \text{m from the vertex.}"),
        EX("Worked example 2: from focus and directrix", intro=r"Find the equation of the parabola with focus $(3, 0)$ and directrix $x = -3$.", steps=[
            S("Let $P(x, y)$ be on the curve. Distance to focus", math=r"PF^2 = (x - 3)^2 + y^2"),
            S("Distance to the directrix", math=r"PM = x + 3"),
            S("Set $PF^2 = PM^2$ and expand", math=r"x^2 - 6x + 9 + y^2 = x^2 + 6x + 9"),
            S("Simplify", math=r"y^2 = 12x"),
        ], check=r"a = 3 \Rightarrow y^2 = 4(3)x = 12x\ \checkmark"),
        EX("Worked example 3: a translated parabola", intro=r"Find the vertex, focus and directrix of $y^2 - 4y - 8x + 20 = 0$.", steps=[
            S("Complete the square in $y$", math=r"(y - 2)^2 - 4 - 8x + 20 = 0"),
            S("Rearrange to the standard form", math=r"(y - 2)^2 = 8x - 16 = 8(x - 2)"),
            S("Compare with $(y - k)^2 = 4a(x - h)$", math=r"h = 2,\ k = 2,\ 4a = 8 \Rightarrow a = 2"),
            S("Read off", math=r"\text{vertex } (2, 2),\quad \text{focus } (4, 2),\quad \text{directrix } x = 0"),
        ]),
        H("Parametric form"),
        D(r"Every point of $y^2 = 4ax$ can be written $(at^2, 2at)$, because $(2at)^2 = 4a\cdot at^2$. Each value of the parameter $t$ gives one point; $t = 0$ is the vertex.", title="Parametric form",
          formula=r"P(t) = (at^2,\ 2at) \qquad \text{chord through } t_1,\ t_2:\quad 2x - (t_1 + t_2)y + 2a\,t_1t_2 = 0",
          note=r"The chord is a straight line through the two points: you can check it by substituting $(at_1^2, 2at_1)$ and $(at_2^2, 2at_2)$."),
        D(r"The chord through $t_1$ and $t_2$ passes through the focus $(a, 0)$ when $2a + 2a\,t_1t_2 = 0$. So for a **focal chord**:", title="Focal chord",
          formula=r"t_1t_2 = -1, \qquad \text{length of the focal chord } = x_1 + x_2 + 2a",
          note=r"The length comes from $PF = x_1 + a$ and $QF = x_2 + a$, each equal to the distance to the directrix."),
        EX("Worked example 4: a focal chord", intro=r"The point $P$ with parameter $t = 2$ is on $y^2 = 8x$. The chord $PQ$ passes through the focus. Find $Q$ and the length of $PQ$.", steps=[
            S("$a = 2$. The point $P$", math=r"P = (at^2, 2at) = (8, 8)"),
            S("Focal chord: $t_1t_2 = -1$", math=r"t_Q = -\tfrac{1}{2} \;\Rightarrow\; Q = (2\cdot\tfrac{1}{4},\ 2\cdot 2\cdot(-\tfrac{1}{2})) = (\tfrac{1}{2}, -2)"),
            S("Length of $PQ$", math=r"\sqrt{(8 - \tfrac{1}{2})^2 + (8 + 2)^2} = \sqrt{56.25 + 100} = 12.5"),
            S("Shortcut: for a focal chord the length is $x_1 + x_2 + 2a$", math=r"8 + \tfrac{1}{2} + 4 = 12.5"),
        ], check=r"\text{gradient } FP = \tfrac{8}{8 - 2} = \tfrac{4}{3},\quad \text{gradient } FQ = \tfrac{-2}{\frac{1}{2} - 2} = \tfrac{4}{3}\ \text{(same line)}"),
        EX("Worked example 5: a locus", intro=r"$P(at^2, 2at)$ is a point on $y^2 = 4ax$ and $O$ is the origin. Find the locus of the midpoint $M$ of $OP$.", steps=[
            S("Coordinates of $M$", math=r"M = \left(\tfrac{at^2}{2},\ at\right)"),
            S("Eliminate $t$: $y = at$, so $t = \\frac{y}{a}$", math=r"x = \frac{a}{2}\cdot\frac{y^2}{a^2} = \frac{y^2}{2a}"),
            S("Rearrange", math=r"y^2 = 2ax"),
        ], check=r"a = 2,\ t = 1:\ M = (1, 2),\ y^2 = 4 = 2(2)(1)\ \checkmark"),
        EX("Worked example 6: a line touching a parabola", intro=r"Find $c$ so that $y = 2x + c$ is a tangent to $y^2 = 8x$, and find the point of contact.", steps=[
            S("Substitute", math=r"(2x + c)^2 = 8x \;\Rightarrow\; 4x^2 + (4c - 8)x + c^2 = 0"),
            S("Equal roots: discriminant $= 0$", math=r"(4c - 8)^2 - 16c^2 = 0 \;\Rightarrow\; 64 - 64c = 0 \;\Rightarrow\; c = 1"),
            S("Repeated root", math=r"4x^2 - 4x + 1 = 0 \;\Rightarrow\; x = \tfrac{1}{2},\quad y = 2\cdot\tfrac{1}{2} + 1 = 2"),
        ], check=r"y^2 = 4 = 8\cdot\tfrac{1}{2}\ \checkmark"),
        H("Common mistakes"),
        MISTAKE(r"Reading $a$ as the coefficient of $x$", r"In $y^2 = 12x$ the number $12$ is $4a$, so $a = 3$. The focus is $(3, 0)$, not $(12, 0)$."),
        MISTAKE("Mixing up the direction", r"$y^2 = 4ax$ opens along the $x$-axis; $x^2 = 4ay$ opens along the $y$-axis. A negative sign on the right means the opposite direction: $y^2 = -12x$ opens left, with focus $(-3, 0)$."),
        MISTAKE("Wrong parametric point", r"For $x^2 = 4ay$ the point is $(2at, at^2)$. For $y^2 = 4ax$ it is $(at^2, 2at)$. Substitute into the equation to check."),
        QUIZ(r"What is the focus of $x^2 = 12y$?",
             [r"$(12, 0)$", r"$(3, 0)$", r"$(0, 3)$", r"$(0, 12)$"], 2,
             r"$x^2 = 4ay$ with $4a = 12$ gives $a = 3$. The parabola opens upwards, so the focus is $(0, a) = (0, 3)$.",
             hint=r"Compare with $x^2 = 4ay$.",
             feedback=[r"$12$ is $4a$, not $a$.", r"This is the focus of $y^2 = 12x$. Here $x$ is squared, so the axis is the $y$-axis.", "", r"$12$ is $4a$, so $a = 3$."]),
        QUIZ(r"For $y^2 = 4ax$, the length of the latus rectum is",
             [r"$a$", r"$2a$", r"$4a$", r"$8a$"], 2,
             r"At $x = a$, $y^2 = 4a^2$, so $y = \pm 2a$ and the chord from $-2a$ to $2a$ has length $4a$.",
             feedback=[r"$a$ is the distance from the vertex to the focus.", r"$2a$ is the distance from the focus to the end of the latus rectum, half its length.", "", r"This is too large. $y = \pm 2a$ gives a length of $4a$."]),
        H("Practice questions"),
        PQ(r"Find the equation of the parabola with focus $(0, 2)$ and directrix $y = -2$. Find where the line $y = x$ meets it.",
           r"$P(x, y)$: $x^2 + (y - 2)^2 = (y + 2)^2 \Rightarrow x^2 = 8y$. With $y = x$: $x^2 = 8x$, so $x = 0$ or $x = 8$. The points are $(0, 0)$ and $(8, 8)$."),
        PQ(r"$P(at^2, 2at)$ is on $y^2 = 4ax$ and $F$ is its focus. Show that $PF = a(1 + t^2)$.",
           r"By the definition, $PF$ equals the distance from $P$ to the directrix $x = -a$, which is $at^2 + a = a(1 + t^2)$. Direct check: $PF^2 = (at^2 - a)^2 + 4a^2t^2 = a^2(t^4 + 2t^2 + 1) = a^2(1 + t^2)^2$."),
        PQ(r"The point $P(12, 12)$ lies on $y^2 = 12x$. The chord $PQ$ passes through the focus. Find the coordinates of $Q$ and the length $PQ$.",
           r"$a = 3$, and $P$ has $2at = 6t = 12$, so $t = 2$. For a focal chord $t_Q = -\frac{1}{2}$, so $Q = (3\cdot\frac{1}{4},\ 6\cdot(-\frac{1}{2})) = (\frac{3}{4}, -3)$. $PQ = x_P + x_Q + 2a = 12 + \frac{3}{4} + 6 = 18.75$. Check: $\sqrt{11.25^2 + 15^2} = \sqrt{351.5625} = 18.75$."),
        PQ(r"A dish is $80\ \text{cm}$ across and $10\ \text{cm}$ deep. Find the equation of its cross-section with the vertex at the origin, and the distance of the focus from the vertex.",
           r"Use $y^2 = 4ax$ in cm. The rim point has $y = 40$ and $x = 10$, so $1600 = 40a$ and $a = 40$. The equation is $y^2 = 160x$ and the focus is $40\ \text{cm}$ from the vertex."),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for the focus, directrix or $a$ from an equation. In Paper 2 (Pure Mathematics) you derive the equation from the focus and directrix, or use $(at^2, 2at)$ for chords and loci.", title="Exam link"),
        H("Summary"),
        SUM(r"A parabola is the set of points equidistant from the focus and the directrix; $e = 1$.",
            r"$y^2 = 4ax$: focus $(a, 0)$, directrix $x = -a$, latus rectum $4a$. Translate with $(y - k)^2 = 4a(x - h)$.",
            r"Parametric form: $(at^2, 2at)$; chord through $t_1$, $t_2$: $2x - (t_1 + t_2)y + 2at_1t_2 = 0$.",
            r"A chord through the focus has $t_1t_2 = -1$.",
            "A line touches a parabola when substituting gives a quadratic with discriminant 0."),
    ],
))

# ---------------------------------------------------------------- Conic sections: ellipses and hyperbolas
LESSONS.append(lesson(
    module=MODULE,
    topic="Conic sections",
    title="Ellipses and hyperbolas: foci, eccentricity and sketching",
    slug="pt-ellipses-and-hyperbolas",
    minutes=25,
    summary="Use the two-focus definitions of the ellipse and hyperbola, find a, b, e, foci, directrices and asymptotes, use the parametric forms and the rectangular hyperbola, and sketch both curves.",
    objectives=[
        "Use the sum and difference of focal distances to find equations of ellipses and hyperbolas",
        "Find a, b, the eccentricity, foci, directrices and asymptotes from an equation",
        "Handle translated conics by completing the square",
        "Use the parametric forms and the rectangular hyperbola xy = c²",
    ],
    key_concepts=["Ellipse", "Hyperbola", "Foci", "Eccentricity", "Asymptotes", "Parametric forms", "Rectangular hyperbola"],
    blocks=[
        H("Introduction"),
        T(r"A gardener at a school in Yaoundé fixes two pegs in the ground $6\ \text{m}$ apart, ties a loop of string of length $16\ \text{m}$ round them and draws the curve with a stick that keeps the string tight. The curve is an **ellipse**, and the pegs are its **foci**. Planets travel on ellipses with the sun at one focus." "\n\n" r"The **hyperbola** is the opposite idea: instead of a fixed sum of distances, it has a fixed difference. Radio navigation systems use this: a ship that picks up signals from two stations can tell it is on a certain hyperbola."),
        H("The ellipse"),
        D(r"An **ellipse** is the set of points $P$ for which $PF_1 + PF_2 = 2a$, a constant greater than $F_1F_2$.", title="Ellipse",
          formula=r"\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1 \quad (a > b > 0), \qquad (a\cos t,\ b\sin t)",
          note=r"Centre $O$, vertices $(\pm a, 0)$, ends of the minor axis $(0, \pm b)$. Foci $(\pm ae, 0)$ where $e$ is the eccentricity, $0 < e < 1$."),
        D(r"The distance $c$ from the centre to a focus is $c = ae$. For the ellipse the numbers are linked by:", title="Relationships for the ellipse",
          formula=r"b^2 = a^2(1 - e^2), \qquad c^2 = a^2 - b^2, \qquad \text{directrices } x = \pm\frac{a}{e}, \qquad \text{area} = \pi ab"),
        IMG("apm-pt-ellipse-foci.svg", alt="The ellipse x squared over 25 plus y squared over 16 equals 1 with foci at (-3, 0) and (3, 0) and a point P joined to both foci, with the two distances adding to 10", caption=r"Figure 1. $\frac{x^2}{25} + \frac{y^2}{16} = 1$. For every point $P$ on the curve, $PF_1 + PF_2 = 10 = 2a$."),
        EX("Worked example 1: the gardener's ellipse", intro=r"Pegs at $(-3, 0)$ and $(3, 0)$, and a string loop of total length $16\ \text{m}$. The loop passes round the two pegs, so the sum of the distances from the pencil to the pegs is $16 - 6 = 10\ \text{m}$. Find the equation and the eccentricity.", steps=[
            S("The sum of distances is $2a$", math=r"2a = 10 \Rightarrow a = 5"),
            S("The foci are at $\\pm c$ with $c = 3$", math=r"b^2 = a^2 - c^2 = 25 - 9 = 16"),
            S("Equation", math=r"\frac{x^2}{25} + \frac{y^2}{16} = 1"),
            S("Eccentricity", math=r"e = \frac{c}{a} = \frac{3}{5}"),
        ], check=r"P = (5\cos 0.7,\ 4\sin 0.7):\ PF_1 + PF_2 = 10.000"),
        EX("Worked example 2: a translated ellipse", intro=r"Find the centre, the lengths of the semi-axes, the eccentricity and the foci of $4x^2 + 9y^2 - 16x + 18y - 11 = 0$.", steps=[
            S("Group and complete the squares", math=r"4(x^2 - 4x) + 9(y^2 + 2y) = 11 \;\Rightarrow\; 4(x - 2)^2 - 16 + 9(y + 1)^2 - 9 = 11"),
            S("Move constants and divide by 36", math=r"4(x - 2)^2 + 9(y + 1)^2 = 36 \;\Rightarrow\; \frac{(x - 2)^2}{9} + \frac{(y + 1)^2}{4} = 1"),
            S("Read off", math=r"\text{centre } (2, -1), \quad a = 3,\ b = 2"),
            S("Eccentricity and focal distance", math=r"e^2 = 1 - \tfrac{4}{9} = \tfrac{5}{9} \Rightarrow e = \tfrac{\sqrt{5}}{3}, \qquad c = ae = \sqrt{5}"),
            S("The major axis is horizontal, so the foci are $c$ to the left and right of the centre", math=r"(2 \pm \sqrt{5},\ -1)"),
        ], check=r"\text{point } (5, -1):\ \text{distances to the foci } (3 - \sqrt{5}) + (3 + \sqrt{5}) = 6 = 2a"),
        H("The hyperbola"),
        D(r"A **hyperbola** is the set of points $P$ for which $|PF_1 - PF_2| = 2a$, a constant smaller than $F_1F_2$.", title="Hyperbola",
          formula=r"\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1, \qquad (a\sec t,\ b\tan t), \qquad b^2 = a^2(e^2 - 1), \qquad e > 1",
          note=r"Vertices $(\pm a, 0)$, foci $(\pm ae, 0)$, directrices $x = \pm\frac{a}{e}$, asymptotes $y = \pm\frac{b}{a}x$. Here $c^2 = a^2 + b^2$." "\n\n" r"The curve has two **branches**. The asymptotes are the lines the branches approach but never touch. To find them, replace the $1$ on the right-hand side by $0$: $\frac{x^2}{a^2} - \frac{y^2}{b^2} = 0$ gives $y = \pm\frac{b}{a}x$."),
        IMG("apm-pt-hyperbola-asymptotes.svg", alt="The hyperbola x squared over 9 minus y squared over 16 equals 1 with two branches, vertices (3, 0) and (-3, 0), foci (5, 0) and (-5, 0) and dashed asymptotes y equals plus and minus 4x over 3", caption=r"Figure 2. $\frac{x^2}{9} - \frac{y^2}{16} = 1$ with vertices $(\pm 3, 0)$, foci $(\pm 5, 0)$ and asymptotes $y = \pm\frac{4}{3}x$."),
        EX("Worked example 3: a hyperbola from its foci", intro=r"A hyperbola has foci $(\pm 5, 0)$ and the difference of the distances from any point to the foci is $6$. Find its equation, eccentricity and asymptotes.", steps=[
            S("The difference is $2a$", math=r"2a = 6 \Rightarrow a = 3"),
            S("The foci are at $\\pm c$ with $c = 5$", math=r"b^2 = c^2 - a^2 = 25 - 9 = 16"),
            S("Equation", math=r"\frac{x^2}{9} - \frac{y^2}{16} = 1"),
            S("Eccentricity", math=r"e = \frac{c}{a} = \frac{5}{3}"),
            S("Asymptotes", math=r"y = \pm\frac{4}{3}x"),
        ], check=r"P = (3\sec 0.6,\ 4\tan 0.6):\ |PF_1 - PF_2| = 6.000"),
        KEY("Which conic is it?", r"Look at the signs of $x^2$ and $y^2$ after you collect terms.", cards=[
            [r"Same sign, equal coefficients", r"$x^2 + y^2 + \dots = 0$: a **circle**."],
            [r"Same sign, different coefficients", "An **ellipse**. Divide so that the right-hand side is $1$."],
            [r"Opposite signs", "A **hyperbola**. The positive term tells you which way the branches open."],
            [r"Only one of $x^2$, $y^2$", "A **parabola**."],
        ]),
        H("The rectangular hyperbola"),
        D(r"If $a = b$ the asymptotes are at right angles and the hyperbola is **rectangular**. Turned so that the asymptotes are the axes, its equation is", title="Rectangular hyperbola",
          formula=r"xy = c^2, \qquad (ct,\ \tfrac{c}{t}), \qquad e = \sqrt{2}",
          note=r"Vertices $(c, c)$ and $(-c, -c)$, foci $(\pm c\sqrt{2},\ \pm c\sqrt{2})$. This is the shape of the graph of $y = \frac{k}{x}$ you know from inverse variation."),
        EX("Worked example 4: xy = 16", intro=r"For the hyperbola $xy = 16$, write down its parametric form, find the point with $t = 2$, and the points of the curve nearest the origin.", steps=[
            S("Here $c^2 = 16$, so $c = 4$. Parametric form", math=r"\left(4t,\ \tfrac{4}{t}\right)"),
            S("The point with $t = 2$", math=r"(8,\ 2) \quad (8 \times 2 = 16\ \checkmark)"),
            S("Squared distance from the origin", math=r"d^2 = 16t^2 + \frac{16}{t^2}"),
            S(r"For positive numbers $u + \frac{1}{u} \geq 2$, so $d^2 = 16\left(t^2 + \frac{1}{t^2}\right) \geq 32$, with equality when $t^2 = 1$", math=r"t = \pm 1 \Rightarrow (4, 4) \text{ and } (-4, -4), \qquad d = \sqrt{32} = 4\sqrt{2}"),
        ], check=r"\text{these are the vertices } (c, c) \text{ and } (-c, -c)"),
        H("Common mistakes"),
        MISTAKE(r"Taking $a^2$ as the larger number for a hyperbola", r"For an ellipse $a > b$ (the larger denominator is $a^2$). For a hyperbola $a^2$ is the denominator of the **positive** term, and $a$ can be smaller than $b$. In $\frac{y^2}{9} - \frac{x^2}{16} = 1$ the branches open up and down, with $a = 3$, $b = 4$."),
        MISTAKE(r"Using $c^2 = a^2 - b^2$ for a hyperbola", r"Ellipse: $c^2 = a^2 - b^2$. Hyperbola: $c^2 = a^2 + b^2$. For the hyperbola $c > a$, so $e = \frac{c}{a} > 1$."),
        MISTAKE("Asymptotes with the wrong gradient", r"For $\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1$ the gradient is $\pm\frac{b}{a}$. Check against the picture: a hyperbola with wide $a$ and narrow $b$ has asymptotes that lie flat."),
        QUIZ(r"What are the foci of $\dfrac{x^2}{25} + \dfrac{y^2}{9} = 1$?",
             [r"$(\pm 4, 0)$", r"$(\pm 5, 0)$", r"$(\pm\sqrt{34}, 0)$", r"$(0, \pm 4)$"], 0,
             r"$a^2 = 25$, $b^2 = 9$, so $c^2 = 25 - 9 = 16$ and $c = 4$. The major axis is along $x$, so the foci are $(\pm 4, 0)$.",
             hint=r"For an ellipse, $c^2 = a^2 - b^2$.",
             feedback=["", r"These are the vertices, at distance $a$ from the centre.", r"You added: $25 + 9 = 34$. That is the hyperbola formula.", r"$a > b$, so the major axis is horizontal."]),
        QUIZ(r"What is the eccentricity of $\dfrac{x^2}{9} - \dfrac{y^2}{16} = 1$?",
             [r"$\frac{3}{5}$", r"$\frac{4}{3}$", r"$\frac{5}{3}$", r"$\frac{\sqrt{7}}{3}$"], 2,
             r"$c^2 = 9 + 16 = 25$, so $c = 5$ and $e = \frac{c}{a} = \frac{5}{3}$.",
             feedback=[r"This is $\frac{a}{c}$, upside down. It would be an ellipse value less than 1.", r"This is $\frac{b}{a}$, the gradient of the asymptote.", "", r"You used $\sqrt{16 - 9} = \sqrt{7}$, the ellipse formula."]),
        H("Practice questions"),
        PQ(r"The ellipse $9x^2 + 16y^2 = 144$ is given. Find the eccentricity, the foci and the equations of the directrices.",
           r"Divide by 144: $\frac{x^2}{16} + \frac{y^2}{9} = 1$, so $a = 4$, $b = 3$. $e^2 = 1 - \frac{9}{16} = \frac{7}{16}$, $e = \frac{\sqrt{7}}{4}$. Foci $(\pm ae, 0) = (\pm\sqrt{7}, 0)$. Directrices $x = \pm\frac{a}{e} = \pm\frac{16}{\sqrt{7}}$."),
        PQ(r"The hyperbola $\dfrac{y^2}{9} - \dfrac{x^2}{16} = 1$ has branches that open up and down. Find the eccentricity, the foci and the asymptotes.",
           r"Here $a^2 = 9$ goes with $y$, and $b^2 = 16$. $c^2 = 9 + 16 = 25$, so $c = 5$ and $e = \frac{5}{3}$. The foci are on the $y$-axis: $(0, \pm 5)$. Asymptotes: $\frac{y^2}{9} = \frac{x^2}{16}$, so $y = \pm\frac{3}{4}x$."),
        PQ(r"The point $P(4\cos t,\ 3\sin t)$ lies on the ellipse $\dfrac{x^2}{16} + \dfrac{y^2}{9} = 1$. A rectangle has vertices at $(\pm 4\cos t, \pm 3\sin t)$ with $0 < t < \frac{\pi}{2}$. Show that its area is $24\sin 2t$, and find the greatest area.",
           r"The sides are $8\cos t$ and $6\sin t$, so the area is $48\sin t\cos t = 24\sin 2t$. The greatest value of $\sin 2t$ is $1$ at $t = \frac{\pi}{4}$, so the greatest area is $24$."),
        PQ(r"Find the point of the hyperbola $xy = 9$ nearest the origin in the first quadrant and its distance from the origin.",
           r"$(3t, \frac{3}{t})$ with $t > 0$ has $d^2 = 9t^2 + \frac{9}{t^2} = 9\left(t^2 + \frac{1}{t^2}\right) \geq 18$, with equality at $t = 1$. The point is $(3, 3)$ and $d = \sqrt{18} = 3\sqrt{2} \approx 4.24$."),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for the eccentricity, foci or asymptotes, and which conic a given equation is. In Paper 2 (Pure Mathematics) you derive an equation from the foci, complete squares to find the centre, and use the parametric forms.", title="Exam link"),
        H("Summary"),
        SUM(r"Ellipse: $PF_1 + PF_2 = 2a$; $\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1$; $b^2 = a^2(1 - e^2)$; foci $(\pm ae, 0)$; $(a\cos t, b\sin t)$.",
            r"Hyperbola: $|PF_1 - PF_2| = 2a$; $\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1$; $b^2 = a^2(e^2 - 1)$; asymptotes $y = \pm\frac{b}{a}x$; $(a\sec t, b\tan t)$.",
            r"Rectangular hyperbola $xy = c^2$: $(ct, \frac{c}{t})$, asymptotes the axes, $e = \sqrt{2}$.",
            r"Directrices are $x = \pm\frac{a}{e}$ for both curves.",
            "For a translated conic, complete the square first and read the centre."),
    ],
))

# ---------------------------------------------------------------- Conic sections: tangents and normals
LESSONS.append(lesson(
    module=MODULE,
    topic="Conic sections",
    title="Tangents and normals to conics using parameters",
    slug="pt-tangents-and-normals-to-conics",
    minutes=25,
    summary="Use parametric differentiation to find tangents and normals to a parabola, ellipse, hyperbola and rectangular hyperbola, then use the parameter to solve problems on intersections and areas.",
    objectives=[
        "Find dy/dx for a conic from its parametric equations",
        "Write down and use the tangent and normal at a general point of each conic",
        "Find where a normal meets the curve again and where two tangents meet",
        "Prove properties such as a constant area using the parameter",
    ],
    key_concepts=["Parametric differentiation", "Tangent", "Normal", "Parameter t", "Point of intersection of tangents", "Constant area"],
    blocks=[
        H("Introduction"),
        T(r"A torch reflector is a parabola. A ray from the bulb at the focus hits the surface and bounces out parallel to the axis. The reason lies in the **tangent**: at the point of contact the reflector acts like a mirror whose surface is the tangent line, and the **normal** is the line at right angles to the mirror."),
        T(r"For a conic written in terms of a parameter $t$, the tangent and normal at the point with parameter $t$ have neat equations, and you can find them once and for all. Then the work in exam questions reduces to substituting a value of $t$."),
        H("The method"),
        D(r"If $x$ and $y$ are given in terms of $t$ (radians if trigonometric), the gradient of the curve is", title="Parametric differentiation",
          formula=r"\frac{dy}{dx} = \frac{dy/dt}{dx/dt}",
          note=r"The tangent has gradient $m$. The normal is perpendicular to the tangent, so it has gradient $-\frac{1}{m}$. Both pass through the point $(x_1, y_1)$ and have equation $y - y_1 = m(x - x_1)$."),
        KEY("Tangent and normal at the point with parameter t", r"All four are found by the method above. Each can be checked by substituting the point.", cards=[
            [r"Parabola $y^2 = 4ax$, point $(at^2, 2at)$", r"Gradient $\frac{1}{t}$. Tangent: $ty = x + at^2$. Normal: $y + tx = 2at + at^3$."],
            [r"Ellipse $\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1$, point $(a\cos t, b\sin t)$", r"Gradient $-\frac{b\cos t}{a\sin t}$. Tangent: $\frac{x\cos t}{a} + \frac{y\sin t}{b} = 1$. Normal: $\frac{ax}{\cos t} - \frac{by}{\sin t} = a^2 - b^2$."],
            [r"Hyperbola $\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1$, point $(a\sec t, b\tan t)$", r"Gradient $\frac{b}{a\sin t}$. Tangent: $\frac{x\sec t}{a} - \frac{y\tan t}{b} = 1$. Normal: $ax\cos t + by\cot t = a^2 + b^2$."],
            [r"Rectangular hyperbola $xy = c^2$, point $(ct, \frac{c}{t})$", r"Gradient $-\frac{1}{t^2}$. Tangent: $x + t^2y = 2ct$. Normal: $t^3x - ty = c(t^4 - 1)$."],
        ]),
        T(r"**Where one comes from.** For the parabola, $x = at^2$ and $y = 2at$ give $\frac{dx}{dt} = 2at$ and $\frac{dy}{dt} = 2a$, so $\frac{dy}{dx} = \frac{1}{t}$. The tangent is $y - 2at = \frac{1}{t}(x - at^2)$. Multiply by $t$: $ty - 2at^2 = x - at^2$, so $ty = x + at^2$. The normal has gradient $-t$: $y - 2at = -t(x - at^2)$, so $y + tx = 2at + at^3$."),
        IMG("apm-pt-tangent-normal.svg", alt="The parabola y squared equals 8x with the point P(2, 4), the tangent y equals x plus 2 and the normal x plus y equals 6 drawn at right angles at P", caption=r"Figure 1. On $y^2 = 8x$ the point with $t = 1$ is $P(2, 4)$. The tangent has gradient $1$ and the normal has gradient $-1$."),
        H("Worked examples"),
        EX("Worked example 1: the normal to a parabola", intro=r"The point $P$ on $y^2 = 8x$ has parameter $t = 1$. Find the normal at $P$ and the point $Q$ where it meets the parabola again.", steps=[
            S("$a = 2$, so $P = (at^2, 2at) = (2, 4)$", math=r"\text{normal: } y + tx = 2at + at^3 \;\Rightarrow\; y + x = 4 + 2 = 6"),
            S("Substitute $x = 6 - y$ into $y^2 = 8x$", math=r"y^2 = 8(6 - y) \;\Rightarrow\; y^2 + 8y - 48 = 0"),
            S("Factorize. One root is $y = 4$ (the point $P$)", math=r"(y - 4)(y + 12) = 0 \;\Rightarrow\; y = -12"),
            S("Find $x$", math=r"x = 6 - (-12) = 18 \;\Rightarrow\; Q = (18, -12)"),
            S("The parameter of $Q$: $2at = 4t = -12$", math=r"t = -3"),
        ], check=r"(-12)^2 = 144 = 8(18)\ \checkmark \qquad \text{and } t_Q = -t_P - \tfrac{2}{t_P} = -3"),
        EX("Worked example 2: tangent and normal to an ellipse", intro=r"Find the tangent and normal to $\dfrac{x^2}{25} + \dfrac{y^2}{9} = 1$ at $P\left(3, \dfrac{12}{5}\right)$.", steps=[
            S("Check $P$ is on the curve and find $t$", math=r"\tfrac{9}{25} + \tfrac{144/25}{9} = \tfrac{9}{25} + \tfrac{16}{25} = 1; \qquad 5\cos t = 3,\ 3\sin t = \tfrac{12}{5} \Rightarrow \cos t = \tfrac{3}{5},\ \sin t = \tfrac{4}{5}"),
            S("Tangent: $\\frac{x\\cos t}{5} + \\frac{y\\sin t}{3} = 1$", math=r"\tfrac{3x}{25} + \tfrac{4y}{15} = 1 \;\Rightarrow\; 9x + 20y = 75"),
            S("Normal: $\\frac{5x}{\\cos t} - \\frac{3y}{\\sin t} = 25 - 9$", math=r"\tfrac{25x}{3} - \tfrac{15y}{4} = 16 \;\Rightarrow\; 100x - 45y = 192"),
        ], check=r"9(3) + 20(2.4) = 75,\quad 100(3) - 45(2.4) = 192,\quad \text{gradients } -\tfrac{9}{20} \text{ and } \tfrac{20}{9} \text{ (product } -1)"),
        EX("Worked example 3: a constant area", intro=r"The tangent at $P(ct, \frac{c}{t})$ to $xy = c^2$ meets the axes at $A$ and $B$. Show that the area of triangle $OAB$ is the same for every $t$. Check with $c = 2$, $t = 3$.", steps=[
            S("Gradient", math=r"x = ct,\ y = \tfrac{c}{t}:\ \tfrac{dy}{dt} = -\tfrac{c}{t^2},\ \tfrac{dx}{dt} = c \;\Rightarrow\; \tfrac{dy}{dx} = -\tfrac{1}{t^2}"),
            S("Tangent", math=r"y - \tfrac{c}{t} = -\tfrac{1}{t^2}(x - ct) \;\Rightarrow\; x + t^2y = 2ct"),
            S("Intercepts: $y = 0$ gives $A$, $x = 0$ gives $B$", math=r"A = (2ct,\ 0), \qquad B = \left(0,\ \tfrac{2c}{t}\right)"),
            S("Area", math=r"\tfrac{1}{2}\cdot 2ct\cdot\tfrac{2c}{t} = 2c^2"),
            S("The area does not contain $t$, so it is constant. For $c = 2$, $t = 3$:", math=r"x + 9y = 12;\quad A = (12, 0),\ B = (0, \tfrac{4}{3}),\quad \text{area } = \tfrac{1}{2}\cdot 12\cdot\tfrac{4}{3} = 8 = 2c^2"),
        ]),
        EX("Worked example 4: where two tangents meet", intro=r"Tangents to $y^2 = 8x$ are drawn at the points with parameters $t = 1$ and $t = 3$. Find the point where they meet.", steps=[
            S("Tangent at $t = 1$: $ty = x + at^2$ with $a = 2$", math=r"y = x + 2"),
            S("Tangent at $t = 3$", math=r"3y = x + 18"),
            S("Subtract to eliminate $x$", math=r"3y - y = 18 - 2 \;\Rightarrow\; y = 8"),
            S("Find $x$", math=r"x = 8 - 2 = 6"),
        ], check=r"\text{general result: tangents at } t_1, t_2 \text{ meet at } (a\,t_1t_2,\ a(t_1 + t_2)) = (6, 8)"),
        EX("Worked example 5: a hyperbola", intro=r"Find the tangent and normal to $\dfrac{x^2}{16} - \dfrac{y^2}{9} = 1$ at $P(8, 3\sqrt{3})$.", steps=[
            S("Find $t$: $4\\sec t = 8$, so $\\sec t = 2$ and $t = 60^\\circ$", math=r"\tan t = \sqrt{3}, \qquad 3\tan t = 3\sqrt{3}\ \checkmark"),
            S("Tangent: $\\frac{x\\sec t}{4} - \\frac{y\\tan t}{3} = 1$", math=r"\tfrac{x}{2} - \tfrac{y}{\sqrt{3}} = 1 \;\Rightarrow\; \sqrt{3}\,x - 2y = 2\sqrt{3}"),
            S("Normal: $4x\\cos t + 3y\\cot t = 25$", math=r"2x + \sqrt{3}\,y = 25"),
        ], check=r"\sqrt{3}(8) - 2(3\sqrt{3}) = 2\sqrt{3},\quad 2(8) + \sqrt{3}(3\sqrt{3}) = 25"),
        H("Common mistakes"),
        MISTAKE("Using the tangent gradient for the normal", r"The normal gradient is $-\frac{1}{m}$. For the parabola the tangent gradient is $\frac{1}{t}$ and the normal gradient is $-t$."),
        MISTAKE("Substituting the wrong value of the parameter", r"Find $t$ from the coordinates of the point first. On $y^2 = 8x$ the point $(8, 8)$ has $4t = 8$, so $t = 2$, not $t = 8$."),
        MISTAKE("Not checking the point is on the curve", r"If the point is not on the curve the formulas give a meaningless line. Substitute the point into the cartesian equation first."),
        MISTAKE("Losing the second intersection", r"When a normal meets the curve again, the quadratic has two roots: one is the known point. Check that you take the other root."),
        QUIZ(r"What is the gradient of the tangent to $y^2 = 8x$ at the point $(8, 8)$?",
             [r"$\frac{1}{2}$", r"$2$", r"$\frac{1}{8}$", r"$-\frac{1}{2}$"], 0,
             r"$a = 2$, and $2at = 4t = 8$ gives $t = 2$. The gradient is $\frac{1}{t} = \frac{1}{2}$. (Or: $2y\frac{dy}{dx} = 8$, so $\frac{dy}{dx} = \frac{4}{y} = \frac{1}{2}$.)",
             hint=r"Find $t$ from $2at = y$, then use gradient $\frac{1}{t}$.",
             feedback=["", r"You used $t$ as the gradient. The gradient is $\frac{1}{t}$.", r"You used $t = 8$. The parameter comes from $4t = 8$.", r"That is the sign of a different quantity: the tangent gradient here is positive because the curve rises at $(8, 8)$."]),
        QUIZ(r"The tangent to $xy = c^2$ at $(ct, \frac{c}{t})$ has gradient $-\frac{1}{t^2}$. What is the gradient of the normal?",
             [r"$-t^2$", r"$\frac{1}{t^2}$", r"$t^2$", r"$-\frac{1}{t}$"], 2,
             r"The normal gradient is the negative reciprocal: $-\frac{1}{-1/t^2} = t^2$.",
             feedback=[r"You took the reciprocal but forgot to change the sign.", r"You only changed the sign. The reciprocal is also needed.", "", r"The tangent gradient is $-\frac{1}{t^2}$, not $-\frac{1}{t}$."]),
        H("Practice questions"),
        PQ(r"The tangents to the parabola $y^2 = 4ax$ at the ends of a focal chord $PQ$ meet at $T$. Show that $T$ lies on the directrix. Check with $a = 2$, $t_P = 2$.",
           r"Let the parameters be $t_1$ and $t_2$ with $t_1t_2 = -1$ (focal chord). The tangents $t_1y = x + at_1^2$ and $t_2y = x + at_2^2$ meet at $(at_1t_2,\ a(t_1 + t_2))$. Since $t_1t_2 = -1$ the $x$-coordinate is $-a$, which is the directrix $x = -a$. Check: $a = 2$, $t_1 = 2$, $t_2 = -\frac{1}{2}$: tangents $2y = x + 8$ and $-\frac{1}{2}y = x + \frac{1}{2}$ meet at $(-2, 3)$; $2(3) = -2 + 8$ and $-\frac{1}{2}(3) = -2 + \frac{1}{2}$."),
        PQ(r"Find the equations of the tangent and normal to the ellipse $\dfrac{x^2}{16} + \dfrac{y^2}{9} = 1$ at the point with parameter $t = \frac{\pi}{3}$.",
           r"$P = \left(4\cos\frac{\pi}{3},\ 3\sin\frac{\pi}{3}\right) = \left(2,\ \frac{3\sqrt{3}}{2}\right)$. Tangent: $\frac{x\cos t}{4} + \frac{y\sin t}{3} = 1$ gives $\frac{x}{8} + \frac{\sqrt{3}y}{6} = 1$, so $3x + 4\sqrt{3}\,y = 24$. Normal: $\frac{4x}{\cos t} - \frac{3y}{\sin t} = 16 - 9$ gives $8x - 2\sqrt{3}\,y = 7$. Check $P$: $6 + 18 = 24$ and $16 - 9 = 7$."),
        PQ(r"The normal to $y^2 = 12x$ at the point $P(3, 6)$ meets the parabola again at $Q$. Find the coordinates of $Q$.",
           r"$a = 3$ and $6t = 6$ gives $t = 1$. Normal: $y + tx = 2at + at^3$ gives $y + x = 6 + 3 = 9$. Substitute $x = 9 - y$: $y^2 = 12(9 - y)$, so $y^2 + 12y - 108 = 0$, $(y - 6)(y + 18) = 0$. $y = -18$ gives $x = 27$. $Q = (27, -18)$. Check: $324 = 12 \times 27$."),
        PQ(r"The tangent at $P(3t, \frac{3}{t})$ to the hyperbola $xy = 9$ meets the $x$-axis at $A$ and the $y$-axis at $B$. Find the area of triangle $OAB$ in terms of $t$ and comment.",
           r"Tangent: $x + t^2y = 6t$. $A = (6t, 0)$ and $B = \left(0, \frac{6}{t}\right)$. Area $= \frac{1}{2}(6t)\left(\frac{6}{t}\right) = 18$. The area does not depend on $t$: it is $2c^2 = 18$ for every tangent."),
        TIP(r"Exam link: Paper 1 (multiple choice) asks for a tangent gradient or whether a normal passes through a given point. In Paper 2 (Pure Mathematics) you derive the tangent or normal at $(at^2, 2at)$ or $(a\cos t, b\sin t)$, then use it to find an intersection or an area.", title="Exam link"),
        H("Summary"),
        SUM(r"$\frac{dy}{dx} = \frac{dy/dt}{dx/dt}$; the normal has gradient $-\frac{1}{m}$.",
            r"Parabola $(at^2, 2at)$: tangent $ty = x + at^2$, normal $y + tx = 2at + at^3$.",
            r"Ellipse $(a\cos t, b\sin t)$: tangent $\frac{x\cos t}{a} + \frac{y\sin t}{b} = 1$.",
            r"Rectangular hyperbola $(ct, \frac{c}{t})$: tangent $x + t^2y = 2ct$; the triangle with the axes has area $2c^2$.",
            r"Tangents to $y^2 = 4ax$ at $t_1$ and $t_2$ meet at $(at_1t_2, a(t_1 + t_2))$; for a focal chord this point is on the directrix."),
    ],
))
